#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    unsigned long long x;
    if (n < 0) {
        putchar('-');
        x = -(unsigned long long)n;
    } else {
        x = (unsigned long long)n;
    }
    if (x == 0) {
        puts("0");
        return 0;
    }
    char s[65];
    int i = 0;
    while (x) {
        s[i++] = (char)('0' + (x & 1ULL));
        x >>= 1;
    }
    while (i > 0) putchar(s[--i]);
    putchar('\n');
    return 0;
}

#include <stdio.h>

int main(void) {
    long long a, b, m;
    if (scanf("%lld %lld %lld", &a, &b, &m) != 3) return 0;
    if (m == 1) {
        printf("0\n");
        return 0;
    }
    long long r = 1 % m;
    a %= m;
    if (a < 0) a += m;
    while (b > 0) {
        if (b & 1) r = (__int128)r * a % m;
        a = (__int128)a * a % m;
        b >>= 1;
    }
    printf("%lld\n", r);
    return 0;
}

