int main(void) {
    size_t cap = 4096, n = 0;
    char *buf = malloc(cap);
    int c;
    while ((c = getchar()) != EOF) {
        if (n + 1 >= cap) {
            cap *= 2;
            buf = realloc(buf, cap);
        }
        buf[n++] = (char)c;
    }
    buf[n] = '\0';

    size_t best_start = 0, best_len = 0, start = 0;
    for (size_t i = 0; ; i++) {
        if (buf[i] == '\0' || isspace((unsigned char)buf[i])) {
            size_t len = i - start;
            if (len > best_len) {
                best_start = start;
                best_len = len;
            }
            if (buf[i] == '\0') break;
            start = i + 1;
        }
    }

    if (best_len > 0) {
        printf("%.*s\n", (int)best_len, buf + best_start);
    }

    free(buf);
    return 0;
}

