    size_t cap = 1, len = 0;
    int *a = malloc(cap * sizeof *a);
    if (!a) return 1;
    for (int i = 0; i < n; i++) {
        if (len == cap) {
            cap *= 2;
            int *tmp = realloc(a, cap * sizeof *a);
            if (!tmp) { free(a); return 1; }
            a = tmp;
        }
        if (scanf("%d", &a[len++]) != 1) { free(a); return 1; }
    }
    long long sum = 0;
    for (size_t i = 0; i < len; i++) sum += a[i];
    printf("%lld\n", sum);
    free(a);
    return 0;
}

