#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int cmp_words(const void *a, const void *b)
{
    const char *x = *(const char *const *)a;
    const char *y = *(const char *const *)b;
    return strcmp(x, y);
}

int main(void)
{
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (!buf) return 1;

    for (;;) {
        if (len == cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); return 1; }
            buf = tmp;
        }
        size_t r = fread(buf + len, 1, cap - len, stdin);
        len += r;
        if (r == 0) break;
    }
    buf[len] = '\0';

    size_t n = 0, wc = 0;
    char **words = NULL;
    for (char *p = strtok(buf, " \t\r\n"); p; p = strtok(NULL, " \t\r\n")) {
        if (n == wc) {
            wc = wc ? wc * 2 : 16;
            char **tmp = realloc(words, wc * sizeof *words);
            if (!tmp) { free(words); free(buf); return 1; }
            words = tmp;
        }
        words[n++] = p;
    }

    qsort(words, n, sizeof *words, cmp_words);

    for (size_t i = 0; i < n; i++) {
        if (i) putchar(' ');
        fputs(words[i], stdout);
    }
    if (n) putchar('\n');

    free(words);
    free(buf);
    return 0;
}

