/* Euclid's algorithm using the remainder; works for negatives via llabs. */
static long long gcd(long long x, long long y)
{
    x = llabs(x);
    y = llabs(y);
    while (y != 0) {
        long long r = x % y;  /* C's % follows dividend sign, but operands are nonnegative here */
        x = y;
        y = r;
    }
    return x;  /* gcd(0, 0) is 0 */
}

