/* Fixed-size sieve array: 0 means possibly prime, 1 means composite. */
static char composite[MAX_N + 1];

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 2) {
        return 0;
    }
    if (n > MAX_N) {
        fprintf(stderr, "n exceeds fixed array size\n");
        return 1;
    }

    /* Mark composites. i <= n / i avoids overflow and stops at sqrt(n). */
    for (int i = 2; i <= n / i; ++i) {
        if (!composite[i]) {
            /* Start at i*i because smaller multiples were already marked. */
            for (int j = i * i; j <= n; j += i) {
                composite[j] = 1;
            }
        }
    }

    for (int i = 2; i <= n; ++i) {
        if (!composite[i]) {
            printf("%d\n", i);
        }
    }

    return 0;
}

