/* Dynamic unsigned big integer stored in base 2^32, little-endian limbs. */
typedef struct {
    uint32_t *d;
    size_t n, cap;
} Big;

static void big_init(Big *b) { b->d = NULL; b->n = 0; b->cap = 0; }

static void big_push(Big *b, uint32_t x) {
    if (b->n == b->cap) {
        size_t nc = b->cap ? b->cap * 2 : 8;
        uint32_t *nd = realloc(b->d, nc * sizeof(uint32_t));
        if (!nd) { perror("realloc"); exit(1); }
        b->d = nd;
        b->cap = nc;
    }
    b->d[b->n++] = x;
}

/* Compute b = b * mul + add.  mul and add are small enough that
   limb * mul + carry never overflows uint64_t. */
static void big_mul_add(Big *b, uint64_t mul, uint64_t add) {
    uint64_t carry = add;
    for (size_t i = 0; i < b->n; i++) {
        uint64_t t = (uint64_t)b->d[i] * mul + carry;
        b->d[i] = (uint32_t)t;
        carry = t >> 32;
    }
    while (carry) {
        big_push(b, (uint32_t)carry);
        carry >>= 32;
    }
    if (b->n == 0 && add == 0) {
        /* keep zero represented as an empty limb array */
    }
}

static char *read_all(size_t *out_len) {
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (!buf) { perror("malloc"); exit(1); }
    for (;;) {
        if (len == cap) {
            cap *= 2;
            char *nb = realloc(buf, cap);
            if (!nb) { perror("realloc"); exit(1); }
            buf = nb;
        }
        size_t r = fread(buf + len, 1, cap - len, stdin);
        if (r == 0) break;
        len += r;
    }
    if (len == cap) {
        char *nb = realloc(buf, cap + 1);
        if (!nb) { perror("realloc"); exit(1); }
        buf = nb;
    }
    buf[len] = '\0';
    *out_len = len;
    return buf;
}

int main(void) {
    size_t total_len;
    char *buf = read_all(&total_len);

    /* Skip leading whitespace and an optional plus sign. */
    size_t i = 0;
    while (buf[i] && isspace((unsigned char)buf[i])) i++;
    if (buf[i] == '+') i++;

    size_t start = i;
    while (buf[i] && isdigit((unsigned char)buf[i])) i++;

    if (i == start) {
        /* No digits found: treat as zero. */
        printf("0\n");
        free(buf);
        return 0;
    }

    const char *digits = buf + start;
    size_t dlen = i - start;

    Big b;
    big_init(&b);

    /* Process the decimal string in base-1e9 chunks.  The first chunk may
       have fewer than 9 digits; the rest have exactly 9. */
    size_t pos = 0;
    size_t first = dlen % 9;
    if (first == 0) first = 9;
    if (dlen <= 9) first = dlen;

    uint64_t chunk = 0;
    for (size_t k = 0; k < first; k++) {
        chunk = chunk * 10 + (uint64_t)(digits[pos] - '0');
        pos++;
    }
    big_mul_add(&b, 1ULL, chunk);  /* b = 0 * 1 + first_chunk */

    while (pos < dlen) {
        chunk = 0;
        for (size_t k = 0; k < 9; k++) {
            chunk = chunk * 10 + (uint64_t)(digits[pos] - '0');
            pos++;
        }
        big_mul_add(&b, 1000000000ULL, chunk);  /* b = b * 1e9 + chunk */
    }

    /* Manually count set bits using Brian Kernighan's method. */
    size_t popcount = 0;
    for (size_t k = 0; k < b.n; k++) {
        uint32_t x = b.d[k];
        while (x) {
            x &= x - 1;
            popcount++;
        }
    }

    printf("%zu\n", popcount);

    free(b.d);
    free(buf);
    return 0;
}

#include <stdio.h>

/* Multiply two numbers modulo mod without overflow, even for large moduli. */
static unsigned long long mulmod(unsigned long long a, unsigned long long b,
                                unsigned long long mod) {
    unsigned long long result = 0;
    a %= mod;
    b %= mod;

    while (b != 0) {
        if (b & 1U) {
            /* result + a < 2*mod, so subtract mod instead of overflowing. */
            if (result >= mod - a) {
                result -= mod - a;
            } else {
                result += a;
            }
        }
        b >>= 1;

        /* Double a modulo mod without overflow. */
        if (a >= mod - a) {
            a -= mod - a;
        } else {
            a += a;
        }
    }
    return result;
}

static unsigned long long modpow(long long a, unsigned long long b,
                                unsigned long long m) {
    if (m == 1) {
        return 0;
    }

    /* Reduce a into [0, m-1], handling negative values. */
    long long reduced = a % (long long)m;
    if (reduced < 0) {
        reduced += (long long)m;
    }
    unsigned long long base = (unsigned long long)reduced;
    unsigned long long result = 1 % m;

    /* Standard binary exponentiation. */
    while (b != 0) {
        if (b & 1ULL) {
            result = mulmod(result, base, m);
        }
        base = mulmod(base, base, m);
        b >>= 1;
    }
    return result;
}

int main(void) {
    long long a, b, m;

    if (scanf("%lld %lld %lld", &a, &b, &m) != 3) {
        return 1;
    }
    if (m <= 0) {
        fprintf(stderr, "modulus must be positive\n");
        return 1;
    }
    if (b < 0) {
        fprintf(stderr, "exponent must be non-negative\n");
        return 1;
    }

    printf("%llu\n", modpow(a, (unsigned long long)b, (unsigned long long)m));
    return 0;
}

