    }

    /* phi(0) is undefined; phi(1) is 1. */
    if (n == 0) {
        puts("0");
        return 0;
    }

    unsigned long long result = n;
    unsigned long long temp = n;

    /* Handle the prime factor 2 separately, then only odd divisors. */
    if (temp % 2 == 0) {
        result -= result / 2;
        while (temp % 2 == 0) {
            temp /= 2;
        }
    }

    /* Trial division. Use d <= temp / d instead of d * d <= temp
       to avoid unsigned overflow near the 64-bit limit. */
    for (unsigned long long d = 3; d <= temp / d; d += 2) {
        if (temp % d == 0) {
            result -= result / d;
            while (temp % d == 0) {
                temp /= d;
            }
        }
    }

    /* If temp is still greater than 1, it is one remaining prime factor. */
    if (temp > 1) {
        result -= result / temp;
    }

    printf("%llu\n", result);
    return 0;
}

