static void swap_int(int *x, int *y)
{
    int t = *x;
    *x = *y;
    *y = t;
}

/* Sorts a[lo..hi] in place using recursive quicksort. */
static void quicksort(int *a, size_t lo, size_t hi)
{
    if (lo >= hi) return;                 /* 0 or 1 element is already sorted */

    size_t mid = lo + (hi - lo) / 2;      /* middle pivot avoids common sorted-input worst case */
    int pivot = a[mid];

    size_t i = lo, j = hi;
    while (i <= j) {
        while (a[i] < pivot) ++i;         /* find element too large on the left */
        while (a[j] > pivot) --j;         /* find element too small on the right */
        if (i <= j) {
            if (i != j) swap_int(&a[i], &a[j]);
            ++i;
            --j;                          /* crossed index means this partition is done */
        }
    }

    /* Recurse on the two partitions; indices have crossed, so ranges are disjoint. */
    if (j > 0 && lo < j) quicksort(a, lo, j);
    if (i < hi) quicksort(a, i, hi);
}

int main(void)
{
