            if (scanf("%d", &a[i]) != 1) {
                free(a);
                return 0;
            }
        }

        quicksort(a, 0, n - 1);
    }

    for (size_t i = 0; i < n; ++i) {
        if (i != 0) putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');

    free(a);
    return 0;
}

