/* Merge the two sorted halves [lo, mid) and [mid, hi) into tmp, then copy back. */
static void merge(int *a, int *tmp, size_t lo, size_t mid, size_t hi)
{
    size_t i = lo, j = mid, k = lo;

    while (i < mid && j < hi) {
        if (a[i] <= a[j]) {      /* <= keeps equal elements stable */
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi)  tmp[k++] = a[j++];

    /* Only the touched range needs to be copied back. */
    for (i = lo; i < hi; i++) {
        a[i] = tmp[i];
    }
}

static void merge_sort(int *a, int *tmp, size_t lo, size_t hi)
{
    if (hi - lo <= 1) return;

    /* Midpoint calculation avoids overflow for large indices. */
    size_t mid = lo + (hi - lo) / 2;
    merge_sort(a, tmp, lo, mid);
    merge_sort(a, tmp, mid, hi);
    merge(a, tmp, lo, mid, hi);
}

