}

#include <stdio.h>
#include <stdlib.h>

/* Move the element at position start down the max-heap.
   The heap currently contains indices [0, end), where end is exclusive. */
static void sift_down(int *a, size_t start, size_t end) {
    size_t parent = start;
    size_t child;

    while ((child = 2 * parent + 1) < end) {
        /* Choose the larger child. */
        if (child + 1 < end && a[child] < a[child + 1]) {
            child++;
        }
        /* Stop if the parent is already in the correct place. */
        if (a[parent] >= a[child]) {
            break;
        }
        /* Otherwise swap and continue downward. */
        int tmp = a[parent];
        a[parent] = a[child];
        a[child] = tmp;
        parent = child;
    }
}

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    /* Allocate space for n integers; handle n == 0 safely. */
    int *a = (n == 0) ? NULL : malloc((size_t)n * sizeof *a);
    if (n > 0 && a == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return 1;
        }
    }

    /* Build a max-heap from the unordered array. */
    if (n > 1) {
        for (int i = n / 2 - 1; i >= 0; i--) {
            sift_down(a, (size_t)i, (size_t)n);
        }

        /* Repeatedly move the current maximum to the end. */
        for (int end = n - 1; end > 0; end--) {
            int tmp = a[0];
            a[0] = a[end];
            a[end] = tmp;
            sift_down(a, 0, (size_t)end);
        }
    }

    /* Print the sorted values. */
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", a[i]);
    }
    if (n > 0) {
        putchar('\n');
    }

    free(a);
    return 0;
}

