    if (a == NULL || dp == NULL) {
        free(a);
        free(dp);
        return 1;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            free(dp);
            return 1;
        }
    }

    int best = 0;
    for (int i = 0; i < n; i++) {
        dp[i] = 1; /* Subsequence consisting of a[i] alone */
        for (int j = 0; j < i; j++) {
            /* Extend a strictly increasing subsequence ending at j */
            if (a[j] < a[i] && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
        if (dp[i] > best) {
            best = dp[i];
        }
    }

    printf("%d\n", best);
    free(a);
    free(dp);
    return 0;
}

