int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) {
        /* Empty input or no elements: conventional maximum is 0. */
        printf("0\n");
        return 0;
    }

    long long x, current, best;
    if (scanf("%lld", &x) != 1) {
        printf("0\n");
        return 0;
    }

    /* Start Kadane's state with the first element so all-negative arrays work. */
    current = best = x;

    for (int i = 1; i < n; ++i) {
        if (scanf("%lld", &x) != 1) {
            break;
        }
        /* Either start a new subarray at x or extend the previous one. */
        current = (x > current + x) ? x : current + x;
        if (current > best) {
            best = current;
        }
    }

    printf("%lld\n", best);
    return 0;
}

