#include <stdlib.h>

static int cmp_ll(const void *a, const void *b)
{
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    return (x > y) - (x < y);
}

int main(void)
{
    int n;
    long long capacity;

    if (scanf("%d %lld", &n, &capacity) != 2 || n < 0) {
        return 0;
    }

    /* Weights are stored as long long to avoid overflow while summing. */
    long long *weight = (n > 0) ? malloc((size_t)n * sizeof *weight) : NULL;
    if (n > 0 && weight == NULL) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        if (scanf("%lld", &weight[i]) != 1) {
            free(weight);
            return 0;
        }
    }

    /* Taking the lightest items first maximizes the item count. */
    qsort(weight, (size_t)n, sizeof *weight, cmp_ll);

    long long used = 0;
    int count = 0;
    for (int i = 0; i < n; i++) {
        /* Stop as soon as the next lightest item would exceed capacity. */
        if (used + weight[i] > capacity) {
            break;
        }
        used += weight[i];
        count++;
    }

    printf("%d\n", count);
    free(weight);
    return 0;
}

