static int digit_sum(long long number) {
    unsigned long long value;

    if (number < 0) {
        value = (unsigned long long)(-(number + 1)) + 1ULL;
    } else {
        value = (unsigned long long)number;
    }

    int sum = 0;
    do {
        sum += (int)(value % 10ULL);
        value /= 10ULL;
    } while (value != 0ULL);

    return sum;
}

