static long long reverse_digits(long long number)
{
    int is_negative = number < 0;
    unsigned long long value =
        is_negative
            ? (unsigned long long)(-(number + 1)) + 1ULL
            : (unsigned long long)number;

    unsigned long long reversed = 0;
    while (value != 0) {
        reversed = reversed * 10ULL + (value % 10ULL);
        value /= 10ULL;
    }

    return is_negative ? -(long long)reversed : (long long)reversed;
}

int main(void)
{
    long long number;

    if (scanf("%lld", &number) != 1) {
