static void print_binary(unsigned long long value)
{
    if (value == 0ULL) {
        putchar('0');
        return;
    }

    char bits[64];
    size_t bit_count = 0;

    while (value != 0ULL) {
        bits[bit_count++] = (char)('0' + (value & 1ULL));
        value >>= 1;
    }

    while (bit_count > 0U) {
        putchar(bits[--bit_count]);
    }
}

