static int *read_integers(int count)
{
    if (count <= 0) {
        return NULL;
    }

    int *values = malloc((size_t)count * sizeof *values);
    if (values == NULL) {
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        if (scanf("%d", &values[i]) != 1) {
            free(values);
            return NULL;
        }
    }

    return values;
}

static void rotate_right(const int *source, int count, long long rotation, int *destination)
{
    if (count <= 0) {
        return;
    }

    long long shift = rotation % count;
    if (shift < 0) {
        shift += count;
    }

    for (int i = 0; i < count; ++i) {
        destination[(i + (int)shift) % count] = source[i];
    }
}

static void print_integers(const int *values, int count)
{
    for (int i = 0; i < count; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", values[i]);
    }

    if (count > 0) {
        putchar('\n');
    }
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return 1;
    }

    int *values = read_integers(count);
    if (count > 0 && values == NULL) {
        return 1;
    }

    long long rotation;
    if (scanf("%lld", &rotation) != 1) {
        free(values);
        return 1;
    }

    int *rotated = NULL;
    if (count > 0) {
        rotated = malloc((size_t)count * sizeof *rotated);
        if (rotated == NULL) {
            free(values);
            return 1;
        }
        rotate_right(values, count, rotation, rotated);
    }

    print_integers(rotated != NULL ? rotated : values, count);

    free(values);
    free(rotated);
    return 0;
}

