static size_t remove_duplicates(long long *values, size_t count)
{
    if (count == 0) {
        return 0;
    }

    size_t unique_count = 1;
    for (size_t i = 1; i < count; ++i) {
        if (values[i] != values[unique_count - 1]) {
            values[unique_count] = values[i];
            ++unique_count;
        }
    }
    return unique_count;
}

static void print_values(const long long *values, size_t count)
{
