    if (scanf("%d", &n) != 1) return 0;
    if (n < 0) n = 0;
    Node *head = build_list(n);
    print_reversed(head);
    free_list(head);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static Node *create_node(int value)
{
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return NULL;
    }
    node->value = value;
    node->next = NULL;
    return node;
}

static Node *reverse_list(Node *head)
{
    Node *previous = NULL;
    Node *current = head;

    while (current != NULL) {
        Node *next = current->next;
        current->next = previous;
        previous = current;
        current = next;
    }

    return previous;
}

static void print_list(const Node *head)
{
    const Node *current = head;

    while (current != NULL) {
        printf("%d", current->value);
        if (current->next != NULL) {
            putchar(' ');
        }
        current = current->next;
    }
    putchar('\n');
}

static void free_list(Node *head)
{
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    int count;

    if (scanf("%d", &count) != 1 || count < 0) {
        return 0;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < count; ++i) {
        int value;

        if (scanf("%d", &value) != 1) {
            break;
        }

        Node *node = create_node(value);
        if (node == NULL) {
            free_list(head);
            return 1;
        }

        if (head == NULL) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    head = reverse_list(head);
    print_list(head);
    free_list(head);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct TreeNode {
    int value;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

static TreeNode *create_node(int value) {
    TreeNode *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static TreeNode *insert_node(TreeNode *root, int value) {
    if (root == NULL) {
        return create_node(value);
    }

    TreeNode *current = root;
    while (1) {
        if (value < current->value) {
            if (current->left == NULL) {
                current->left = create_node(value);
                break;
            }
            current = current->left;
        } else {
            if (current->right == NULL) {
                current->right = create_node(value);
                break;
            }
            current = current->right;
        }
    }
    return root;
}

static void push_node(TreeNode **stack, size_t *size, size_t *capacity, TreeNode *node) {
    if (*size == *capacity) {
        size_t new_capacity = (*capacity == 0) ? 8 : *capacity * 2;
        TreeNode **new_stack = realloc(*stack, new_capacity * sizeof *new_stack);
        if (new_stack == NULL) {
            fprintf(stderr, "out of memory\n");
            exit(EXIT_FAILURE);
        }
        *stack = new_stack;
        *capacity = new_capacity;
    }
    (*stack)[(*size)++] = node;
}

static void print_inorder(const TreeNode *root) {
    TreeNode **stack = NULL;
    size_t stack_size = 0;
    size_t stack_capacity = 0;
    const TreeNode *current = root;

    while (current != NULL || stack_size > 0) {
        while (current != NULL) {
            push_node(&stack, &stack_size, &stack_capacity, (TreeNode *)current);
            current = current->left;
        }
        current = stack[--stack_size];
        printf("%d", current->value);
        if (stack_size > 0 || current->right != NULL) {
            putchar(' ');
        }
        current = current->right;
    }
    putchar('\n');

    free(stack);
}

static void free_tree(TreeNode *root) {
    if (root == NULL) {
        return;
    }
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main(void) {
    int count;
    if (scanf("%d", &count) != 1) {
        return 0;
    }

    TreeNode *root = NULL;
    for (int i = 0; i < count; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        root = insert_node(root, value);
    }

    print_inorder(root);
    free_tree(root);
    return 0;
}

#include <stdio.h>

#define STACK_CAPACITY 100

typedef struct {
    int items[STACK_CAPACITY];
    int top;
} IntStack;

static void stack_init(IntStack *stack)
{
    stack->top = -1;
}

static int stack_is_empty(const IntStack *stack)
{
    return stack->top < 0;
}

static int stack_is_full(const IntStack *stack)
{
    return stack->top >= STACK_CAPACITY - 1;
}

static int stack_push(IntStack *stack, int value)
{
    if (stack_is_full(stack)) {
        return 0;
    }

    stack->items[++stack->top] = value;
    return 1;
}

static int stack_pop(IntStack *stack, int *value)
{
    if (stack_is_empty(stack)) {
        return 0;
    }

    *value = stack->items[stack->top--];
    return 1;
}

int main(void)
{
    IntStack stack;
    char command;

    stack_init(&stack);

    while (scanf(" %c", &command) == 1) {
        if (command == 'p') {
            int value;

            if (scanf("%d", &value) != 1) {
                break;
            }

            if (!stack_push(&stack, value)) {
                fprintf(stderr, "stack overflow\n");
            }
        } else if (command == 'o') {
            int value;

            if (stack_pop(&stack, &value)) {
                printf("%d\n", value);
            } else {
                fprintf(stderr, "stack underflow\n");
            }
        } else if (command == 'q') {
            break;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdbool.h>

#define QUEUE_CAPACITY 100

typedef struct {
    int items[QUEUE_CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
} IntQueue;

static void queue_init(IntQueue *queue) {
    queue->head = 0;
    queue->tail = 0;
    queue->count = 0;
}

static bool queue_is_empty(const IntQueue *queue) {
    return queue->count == 0;
}

static bool queue_is_full(const IntQueue *queue) {
    return queue->count == QUEUE_CAPACITY;
}

static bool enqueue(IntQueue *queue, int value) {
    if (queue_is_full(queue)) {
        return false;
    }

    queue->items[queue->tail] = value;
    queue->tail = (queue->tail + 1) % QUEUE_CAPACITY;
    queue->count++;
    return true;
}

static bool dequeue(IntQueue *queue, int *value) {
    if (queue_is_empty(queue)) {
        return false;
    }

    *value = queue->items[queue->head];
    queue->head = (queue->head + 1) % QUEUE_CAPACITY;
    queue->count--;
    return true;
}

int main(void) {
    IntQueue queue;
    queue_init(&queue);

    char command;
    while (scanf(" %c", &command) == 1) {
        if (command == 'e') {
            int value;
            if (scanf("%d", &value) != 1) {
                fprintf(stderr, "Missing value for enqueue\n");
                return 1;
            }

            if (!enqueue(&queue, value)) {
                fprintf(stderr, "Queue is full\n");
            }
        } else if (command == 'd') {
            int value;
            if (dequeue(&queue, &value)) {
                printf("%d\n", value);
            } else {
                fprintf(stderr, "Queue is empty\n");
            }
        } else if (command == 'q') {
            break;
        } else {
            fprintf(stderr, "Unknown command: %c\n", command);
        }
    }

    return 0;
}

