static char *read_line(void) {
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int current_char;
    while ((current_char = getchar()) != EOF && current_char != '\n') {
        if (length + 2 > capacity) {
            size_t new_capacity = capacity * 2;
            char *resized_buffer = realloc(buffer, new_capacity);

            if (resized_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = resized_buffer;
            capacity = new_capacity;
        }

        buffer[length] = (char)current_char;
        length++;
    }

    if (length == 0 && current_char == EOF) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

static char **split_into_words(char *line, size_t *word_count) {
    size_t capacity = 8;
    size_t count = 0;
    char **words = malloc(capacity * sizeof *words);

    if (words == NULL) {
        return NULL;
    }

    for (char *word = strtok(line, " \t\r\n\f\v");
         word != NULL;
         word = strtok(NULL, " \t\r\n\f\v")) {
        if (count == capacity) {
            size_t new_capacity = capacity * 2;
            char **resized_words = realloc(words, new_capacity * sizeof *resized_words);

            if (resized_words == NULL) {
                free(words);
                return NULL;
            }

            words = resized_words;
            capacity = new_capacity;
        }

        words[count] = word;
        count++;
    }

    *word_count = count;
    return words;
}

static int compare_word_pointers(const void *left, const void *right) {
    const char *const *left_word = left;
    const char *const *right_word = right;

    return strcmp(*left_word, *right_word);
}

int main(void) {
    char *line = read_line();

    if (line == NULL) {
        return 0;
    }

    size_t word_count = 0;
    char **words = split_into_words(line, &word_count);

    if (words == NULL) {
        free(line);
        return 1;
    }

    if (word_count > 0) {
        qsort(words, word_count, sizeof *words, compare_word_pointers);

        for (size_t index = 0; index < word_count; index++) {
            if (index > 0) {
                putchar(' ');
            }
            fputs(words[index], stdout);
        }
    }

    putchar('\n');

    free(words);
    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static int roman_digit_value(char symbol)
{
    switch (symbol) {
        case 'I': case 'i': return 1;
        case 'V': case 'v': return 5;
        case 'X': case 'x': return 10;
        case 'L': case 'l': return 50;
        case 'C': case 'c': return 100;
        case 'D': case 'd': return 500;
        case 'M': case 'm': return 1000;
        default: return -1;
    }
}

static long long parse_roman(const char *numeral)
{
    long long total = 0;

    for (size_t index = 0; numeral[index] != '\0'; ++index) {
        int current = roman_digit_value(numeral[index]);
        int next = (numeral[index + 1] != '\0')
                   ? roman_digit_value(numeral[index + 1])
                   : 0;

        if (current < 0 || next < 0) {
            return -1;
        }

        if (next > current) {
            total -= current;
        } else {
            total += current;
        }
    }

    return total;
}

static char *read_all_stdin(void)
{
    size_t capacity = 1024;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int character;
    while ((character = fgetc(stdin)) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *resized = realloc(buffer, capacity);
            if (resized == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = resized;
        }
        buffer[length++] = (char)character;
    }

    buffer[length] = '\0';
    return buffer;
}

int main(void)
{
    char *input = read_all_stdin();
    if (input == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    size_t start = 0;
    while (isspace((unsigned char)input[start])) {
        ++start;
    }

    size_t end = start;
    while (input[end] != '\0' && !isspace((unsigned char)input[end])) {
        ++end;
    }
    input[end] = '\0';

    const char *numeral = input + start;
    long long value = parse_roman(numeral);

    if (value < 0 && numeral[0] != '\0') {
        fprintf(stderr, "invalid Roman numeral: %s\n", numeral);
        free(input);
        return 1;
    }

    printf("%lld\n", value);
    free(input);
    return 0;
}

