#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *text;
    size_t length;
    size_t capacity;
} StringBuilder;

static char *duplicate_string(const char *source) {
    size_t length = strlen(source);
    char *copy = malloc(length + 1);
    if (copy != NULL) {
        memcpy(copy, source, length + 1);
    }
    return copy;
}

static char *add_strings(const char *left, const char *right) {
    size_t left_length = strlen(left);
    size_t right_length = strlen(right);
    size_t max_length = left_length > right_length ? left_length : right_length;

    char *result = malloc(max_length + 2);
    if (result == NULL) {
        return NULL;
    }

    size_t position = max_length + 1;
    result[position] = '\0';
    int carry = 0;
    size_t i = left_length;
    size_t j = right_length;

    while (i > 0 || j > 0 || carry != 0) {
        int digit_left = i > 0 ? left[--i] - '0' : 0;
        int digit_right = j > 0 ? right[--j] - '0' : 0;
        int sum = digit_left + digit_right + carry;
        result[--position] = (char)('0' + (sum % 10));
        carry = sum / 10;
    }

    size_t result_length = (max_length + 1) - position;
    memmove(result, result + position, result_length + 1);

    char *shrunk = realloc(result, result_length + 1);
    return shrunk != NULL ? shrunk : result;
}

static void sb_init(StringBuilder *builder) {
    builder->capacity = 16;
    builder->text = malloc(builder->capacity);
    if (builder->text != NULL) {
        builder->text[0] = '\0';
    }
    builder->length = 0;
}

static void sb_reserve(StringBuilder *builder, size_t extra) {
    if (builder->length + extra + 1 > builder->capacity) {
        size_t new_capacity = builder->capacity;
        while (builder->length + extra + 1 > new_capacity) {
            new_capacity *= 2;
        }
        char *new_text = realloc(builder->text, new_capacity);
        if (new_text != NULL) {
            builder->text = new_text;
            builder->capacity = new_capacity;
        }
    }
}

static void sb_append_char(StringBuilder *builder, char character) {
    sb_reserve(builder, 1);
    if (builder->text != NULL) {
        builder->text[builder->length++] = character;
        builder->text[builder->length] = '\0';
    }
}

static void sb_append(StringBuilder *builder, const char *text) {
    size_t extra = strlen(text);
    sb_reserve(builder, extra);
    if (builder->text != NULL) {
        memcpy(builder->text + builder->length, text, extra + 1);
        builder->length += extra;
    }
}

int main(void) {
    int row_count;

    if (scanf("%d", &row_count) != 1) {
        return 0;
    }
    if (row_count < 0) {
        row_count = 0;
    }

    char **rows = row_count > 0 ? calloc((size_t)row_count, sizeof(char *)) : NULL;
    size_t *widths = row_count > 0 ? calloc((size_t)row_count, sizeof(size_t)) : NULL;

    char **previous_coefficients = NULL;
    size_t previous_count = 0;

    for (int row_index = 0; row_index < row_count; ++row_index) {
        size_t current_count = (size_t)row_index + 1;
        char **current_coefficients = calloc(current_count, sizeof(char *));

        current_coefficients[0] = duplicate_string("1");
        if (current_count > 1) {
            current_coefficients[current_count - 1] = duplicate_string("1");
        }

        for (size_t j = 1; j + 1 < current_count; ++j) {
            current_coefficients[j] = add_strings(
                previous_coefficients[j - 1],
                previous_coefficients[j]
            );
        }

        StringBuilder builder;
        sb_init(&builder);

        for (size_t j = 0; j < current_count; ++j) {
            if (j > 0) {
                sb_append_char(&builder, ' ');
            }
            sb_append(&builder, current_coefficients[j]);
        }

        rows[row_index] = builder.text;
        widths[row_index] = builder.length;

        if (previous_coefficients != NULL) {
            for (size_t j = 0; j < previous_count; ++j) {
                free(previous_coefficients[j]);
            }
            free(previous_coefficients);
        }

        previous_coefficients = current_coefficients;
        previous_count = current_count;
    }

    size_t maximum_width = 0;
    for (int i = 0; i < row_count; ++i) {
        if (widths[i] > maximum_width) {
            maximum_width = widths[i];
        }
    }

    for (int i = 0; i < row_count; ++i) {
        size_t leading_spaces = (maximum_width - widths[i]) / 2;
        for (size_t space = 0; space < leading_spaces; ++space) {
            putchar(' ');
        }
        fputs(rows[i], stdout);
        putchar('\n');
    }

    for (int i = 0; i < row_count; ++i) {
        free(rows[i]);
    }
    free(rows);
    free(widths);

    if (previous_coefficients != NULL) {
        for (size_t j = 0; j < previous_count; ++j) {
            free(previous_coefficients[j]);
        }
        free(previous_coefficients);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int *allocate_matrix(int n)
{
    size_t count = (size_t)n * (size_t)n;
    int *matrix = calloc(count, sizeof *matrix);
    if (matrix == NULL && count != 0) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }
    return matrix;
}

static void fill_spiral(int *matrix, int n)
{
    int top = 0;
    int bottom = n - 1;
    int left = 0;
    int right = n - 1;
    int value = 1;
    int total = n * n;

    while (value <= total) {
        for (int col = left; col <= right && value <= total; ++col) {
            matrix[top * n + col] = value++;
        }
        ++top;

        for (int row = top; row <= bottom && value <= total; ++row) {
            matrix[row * n + right] = value++;
        }
        --right;

        for (int col = right; col >= left && value <= total; --col) {
            matrix[bottom * n + col] = value++;
        }
        --bottom;

        for (int row = bottom; row >= top && value <= total; --row) {
            matrix[row * n + left] = value++;
        }
        ++left;
    }
}

static void print_matrix(const int *matrix, int n)
{
    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < n; ++col) {
            if (col > 0) {
                putchar(' ');
            }
            printf("%d", matrix[row * n + col]);
        }
        putchar('\n');
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        fprintf(stderr, "invalid input\n");
        return EXIT_FAILURE;
    }

    int *matrix = allocate_matrix(n);
    fill_spiral(matrix, n);
    print_matrix(matrix, n);
    free(matrix);

    return EXIT_SUCCESS;
}

