    /* Skip leading whitespace. */
    do {
        c = getchar();
    } while (c != EOF && isspace((unsigned char)c));

    /* Handle empty input. */
    if (c == EOF) {
        printf("0\n");
        return 0;
    }

    /* Optional sign; it does not affect the digit sum. */
    if (c == '-' || c == '+') {
        c = getchar();
    }

    /* Sum decimal digits of the first integer. */
    while (c != EOF && isdigit((unsigned char)c)) {
        sum += c - '0';
