        return NULL;
    }

    int ch;
    while ((ch = getchar()) != EOF) {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            if (new_cap < cap) {
                free(buf);
                return NULL;
            }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return NULL;
            }
