        int composite = 1;
        for (int r = 1; r < s; r++) {
            x = mulmod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }
        if (composite) return 0;
    }
    return 1;
}

static u64 pollard(u64 n) {
    if (n % 2 == 0) return 2;
    if (n % 3 == 0) return 3;

    for (u64 c = 1; ; c++) {
        u64 x = 2, y = 2, d = 1;
        while (d == 1) {
            x = (mulmod(x, x, n) + c) % n;
            y = (mulmod(y, y, n) + c) % n;
            y = (mulmod(y, y, n) + c) % n;
            u64 diff = x > y ? x - y : y - x;
            d = gcd(diff, n);
        }
        if (d != n) return d;
    }
}

#define MAXF 128
static u64 fac[MAXF];
static size_t nfac = 0;

static void factorize(u64 n) {
    if (n == 1) return;
    if (is_prime(n)) {
        if (nfac < MAXF) fac[nfac++] = n;
        return;
    }
    u64 d = pollard(n);
    factorize(d);
    factorize(n / d);
}

static int cmp_u64(const void *a, const void *b) {
    u64 x = *(const u64 *)a;
    u64 y = *(const u64 *)b;
    return (x > y) - (x < y);
}

