static int is_perfect_square_ull(unsigned long long x)
{
    if (x == 0ULL) {
        return 1;
    }

    unsigned long long lo = 1ULL;
    unsigned long long hi = 4294967295ULL; /* floor(sqrt(ULLONG_MAX)) */

    while (lo <= hi) {
        unsigned long long mid = lo + (hi - lo) / 2ULL;
        unsigned long long sq = mid * mid;

        if (sq == x) {
            return 1;
        }
        if (sq < x) {
            lo = mid + 1ULL;
        } else {
            hi = mid - 1ULL;
        }
    }
    return 0;
}

