#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t cap = 128;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return 1;
    }

    int c;
    while ((c = fgetc(stdin)) != EOF && c != '\n') {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            if (new_cap < cap) {
                free(buf);
                return 1;
            }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return 1;
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }

    buf[len] = '\0';
    if (len > 0 && buf[len - 1] == '\r') {
        buf[--len] = '\0';
    }

    size_t left = 0;
    size_t right = len;
    int is_palindrome = 1;

    while (1) {
        while (left < right && buf[left] == ' ') {
            left++;
        }
        while (left < right && buf[right - 1] == ' ') {
            right--;
        }
        if (left >= right) {
            break;
        }
        if (buf[left] != buf[right - 1]) {
            is_palindrome = 0;
            break;
        }
        left++;
        right--;
    }

    printf("%d\n", is_palindrome);
    free(buf);
    return 0;
}

