static void swap(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}

static void quicksort(int *a, int lo, int hi)
{
    if (lo >= hi)
        return;

    int pivot = a[lo + (hi - lo) / 2];
    int lt = lo, gt = hi, i = lo;

    while (i <= gt) {
        if (a[i] < pivot) {
            swap(&a[lt++], &a[i++]);
        } else if (a[i] > pivot) {
            swap(&a[i], &a[gt--]);
        } else {
            ++i;
        }
    }

    quicksort(a, lo, lt - 1);
    quicksort(a, gt + 1, hi);
}

