    Node *tail = NULL;

    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            value = 0;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            free_list(head);
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    head = reverse_list(head);

    for (Node *p = head; p != NULL; p = p->next) {
