#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

static Node *new_node(int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return NULL;
    }
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static Node *insert(Node *root, int value) {
    Node *parent = NULL;
    Node *current = root;

    while (current != NULL) {
        parent = current;
        if (value < current->value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    Node *node = new_node(value);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }

    if (parent == NULL) {
        return node;
    }
    if (value < parent->value) {
        parent->left = node;
    } else {
        parent->right = node;
    }
    return root;
}

static void free_tree(Node *root) {
    if (root == NULL) {
        return;
    }
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main(void) {
    int n = 0;

    if (scanf("%d", &n) != 1 || n < 0) {
        n = 0;
    }

    Node *root = NULL;
    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        root = insert(root, value);
    }

    Node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            fprintf(stderr, "out of memory\n");
            free_tree(root);
            return EXIT_FAILURE;
        }
    }

    size_t top = 0;
    Node *current = root;
    int first = 1;

    while (current != NULL || top > 0) {
        while (current != NULL) {
            stack[top++] = current;
            current = current->left;
        }
        current = stack[--top];

        if (!first) {
            putchar(' ');
        }
        first = 0;
        printf("%d", current->value);

        current = current->right;
    }

    putchar('\n');

    free(stack);
    free_tree(root);
    return 0;
}

