#include <stdio.h>

#define CAPACITY 100

typedef struct {
    int data[CAPACITY];
    int head;
    int tail;
    int count;
} Queue;

static void queue_init(Queue *q) {
    q->head = 0;
    q->tail = 0;
    q->count = 0;
}

static int queue_enqueue(Queue *q, int value) {
    if (q->count == CAPACITY) {
        return 0;
    }
    q->data[q->tail] = value;
    q->tail = (q->tail + 1) % CAPACITY;
    ++q->count;
    return 1;
}

static int queue_dequeue(Queue *q, int *value) {
    if (q->count == 0) {
        return 0;
    }
    *value = q->data[q->head];
    q->head = (q->head + 1) % CAPACITY;
    --q->count;
    return 1;
}

int main(void) {
    Queue q;
    queue_init(&q);

    char command;
    while (scanf(" %c", &command) == 1) {
        if (command == 'q' || command == 'Q') {
            break;
        } else if (command == 'e' || command == 'E') {
            int value;
            if (scanf("%d", &value) == 1) {
                queue_enqueue(&q, value);
            }
        } else if (command == 'd' || command == 'D') {
            int value;
            if (queue_dequeue(&q, &value)) {
                printf("%d\n", value);
            }
        }
    }

    return 0;
}

