#define STACK_SIZE 1024

int main(void) {
    int stack[STACK_SIZE];
    int top = -1;
    int c;

    while ((c = getchar()) != EOF) {
        if (isspace((unsigned char)c))
            continue;

        if (c >= '0' && c <= '9') {
            if (top + 1 >= STACK_SIZE)
                return 1;
            stack[++top] = c - '0';
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            if (top < 1)
                return 1;

            int b = stack[top--];
            int a = stack[top--];
            int result = 0;

            switch (c) {
                case '+': result = a + b; break;
                case '-': result = a - b; break;
                case '*': result = a * b; break;
                case '/':
                    if (b == 0)
                        return 1;
                    result = a / b;
                    break;
            }

            if (top + 1 >= STACK_SIZE)
                return 1;
            stack[++top] = result;
        } else {
            return 1;
        }
    }

    if (top < 0)
        printf("0\n");
    else
        printf("%d\n", stack[top]);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static void skip(const char **p) {
    while (isspace((unsigned char)**p)) {
        (*p)++;
    }
}

int main(void) {
    char *buf = NULL;
    size_t len = 0, cap = 0;
    int ch;

    while ((ch = getchar()) != EOF) {
        if (len + 1 >= cap) {
            cap = cap ? cap * 2 : 4096;
            char *nb = realloc(buf, cap);
            if (!nb) {
                free(buf);
                return 1;
            }
            buf = nb;
        }
        buf[len++] = (char)ch;
    }

    if (!buf) {
        buf = malloc(1);
        if (!buf) {
            return 1;
        }
        buf[0] = '\0';
    } else {
        if (len + 1 > cap) {
            char *nb = realloc(buf, len + 1);
            if (!nb) {
                free(buf);
                return 1;
            }
            buf = nb;
        }
        buf[len] = '\0';
    }

    const char *p = buf;
    skip(&p);

    long long result = 0;
    int sign = 1;

    if (*p == '+' || *p == '-') {
        sign = (*p == '-') ? -1 : 1;
        p++;
        skip(&p);
    }

    if (isdigit((unsigned char)*p)) {
        long long num = 0;
        while (isdigit((unsigned char)*p)) {
            num = num * 10 + (*p - '0');
            p++;
        }
        result = sign * num;
    }

    while (*p) {
        skip(&p);
        if (*p != '+' && *p != '-') {
            break;
        }

        int op = (*p == '+') ? 1 : -1;
        p++;
        skip(&p);

        int nsign = 1;
        if (*p == '+' || *p == '-') {
            nsign = (*p == '-') ? -1 : 1;
            p++;
            skip(&p);
        }

        if (!isdigit((unsigned char)*p)) {
            break;
        }

        long long num = 0;
        while (isdigit((unsigned char)*p)) {
            num = num * 10 + (*p - '0');
            p++;
        }

        result += op * nsign * num;
    }

    printf("%lld\n", result);
    free(buf);
    return 0;
}

