    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return 1;
    }

    for (;;) {
        if (length == capacity) {
            size_t new_capacity = capacity * 2;
            char *tmp = realloc(buffer, new_capacity);
            if (tmp == NULL) {
                free(buffer);
                return 1;
            }
            buffer = tmp;
            capacity = new_capacity;
        }

        size_t read = fread(buffer + length, 1, capacity - length, stdin);
        if (read == 0) {
            break;
        }
        length += read;
    }

    if (ferror(stdin)) {
        free(buffer);
        return 1;
    }

    buffer[length] = '\0';

    size_t word_capacity = 16;
    size_t word_count = 0;
    char **words = malloc(word_capacity * sizeof(*words));

    if (words == NULL) {
        free(buffer);
        return 1;
    }

    char *p = buffer;
    while (*p != '\0') {
        while (*p != '\0' && isspace((unsigned char)*p)) {
            ++p;
        }
        if (*p == '\0') {
            break;
        }

        char *start = p;
        while (*p != '\0' && !isspace((unsigned char)*p)) {
            ++p;
        }
        if (*p != '\0') {
            *p = '\0';
            ++p;
        }

        if (word_count == word_capacity) {
            size_t new_word_capacity = word_capacity * 2;
            char **tmp = realloc(words, new_word_capacity * sizeof(*words));
            if (tmp == NULL) {
                free(words);
                free(buffer);
                return 1;
            }
            words = tmp;
            word_capacity = new_word_capacity;
        }

        words[word_count++] = start;
    }

    qsort(words, word_count, sizeof(*words), compare_words);

    for (size_t i = 0; i < word_count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }

