static int roman_value(char c) {
    switch (c) {
        case 'I': case 'i': return 1;
        case 'V': case 'v': return 5;
        case 'X': case 'x': return 10;
        case 'L': case 'l': return 50;
        case 'C': case 'c': return 100;
        case 'D': case 'd': return 500;
        case 'M': case 'm': return 1000;
        default: return 0;
    }
}

int main(void) {
    size_t cap = 1024, len = 0;
    char *buf = malloc(cap);
    if (!buf) return 1;

    int c;
    while ((c = getchar()) != EOF) {
        if (len + 1 >= cap) {
            size_t newcap = cap * 2;
            char *nb = realloc(buf, newcap);
            if (!nb) {
                free(buf);
                return 1;
            }
            buf = nb;
            cap = newcap;
        }
        buf[len++] = (char)c;
    }
    buf[len] = '\0';

    long long total = 0;
    size_t i = 0;

    while (i < len && isspace((unsigned char)buf[i])) i++;

    while (i < len) {
        int cur = roman_value(buf[i]);
        if (cur <= 0) {
            i++;
            continue;
        }

        size_t j = i + 1;
        while (j < len && isspace((unsigned char)buf[j])) j++;

        if (j < len) {
            int nxt = roman_value(buf[j]);
            if (nxt > cur) total -= cur;
            else total += cur;
        } else {
            total += cur;
        }

        i = j;
    }

    printf("%lld\n", total);
    free(buf);
    return 0;
}

