        return 0;
    }

    long long *matrix = calloc((size_t)n * (size_t)n, sizeof *matrix);
    if (matrix == NULL) {
        return 0;
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    long long value = 1;

    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; ++c) {
            matrix[top * n + c] = value++;
        }
        ++top;

        for (int r = top; r <= bottom; ++r) {
            matrix[r * n + right] = value++;
        }
        --right;

        if (top <= bottom) {
            for (int c = right; c >= left; --c) {
                matrix[bottom * n + c] = value++;
            }
            --bottom;
        }

        if (left <= right) {
            for (int r = bottom; r >= top; --r) {
                matrix[r * n + left] = value++;
            }
            ++left;
        }
    }

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            if (c > 0) {
                putchar(' ');
            }
            printf("%lld", matrix[r * n + c]);
        }
        putchar('\n');
    }

    free(matrix);
    return 0;
}

#include <stdio.h>
