typedef struct {
    char *data;
    size_t len;
    size_t cap;
} Buffer;

static int buf_append(Buffer *b, const char *s, size_t n) {
    if (n == 0) return 0;
    if (b->len + n > b->cap) {
        size_t cap = b->cap ? b->cap : 64;
        while (cap < b->len + n) {
            if (cap > (size_t)-1 / 2) return -1;
            cap *= 2;
        }
        char *p = realloc(b->data, cap);
        if (!p) return -1;
        b->data = p;
        b->cap = cap;
    }
    memcpy(b->data + b->len, s, n);
    b->len += n;
    b->data[b->len] = '\0';
    return 0;
}

static int buf_putc(Buffer *b, char c) {
    return buf_append(b, &c, 1);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) n = 0;
    if (n < 0) n = 0;

    Buffer cur = {0};
    if (buf_append(&cur, "1", 1) != 0) return 1;

    Buffer next = {0};

    for (int i = 0; i < n; i++) {
        if (fputs(cur.data, stdout) == EOF) return 1;
        if (fputc('\n', stdout) == EOF) return 1;

        if (i == n - 1) break;

        next.len = 0;
        size_t j = 0;
        while (j < cur.len) {
            size_t k = j;
            while (k < cur.len && cur.data[k] == cur.data[j]) k++;
            size_t count = k - j;

            char tmp[32];
            int tlen = snprintf(tmp, sizeof tmp, "%zu", count);
            if (tlen < 0) return 1;
            if (buf_append(&next, tmp, (size_t)tlen) != 0) return 1;
            if (buf_putc(&next, cur.data[j]) != 0) return 1;

            j = k;
        }

        Buffer t = cur;
        cur = next;
        next = t;
    }

    free(cur.data);
    free(next.data);
    return 0;
}

