static int append_char(char **buf, size_t *len, size_t *cap, int c) {
    if (*len + 1 >= *cap) {
        size_t new_cap = *cap ? *cap * 2 : 4096;
        while (new_cap < *len + 2) {
            new_cap *= 2;
        }
        char *new_buf = realloc(*buf, new_cap);
        if (new_buf == NULL) {
            return -1;
        }
        *buf = new_buf;
        *cap = new_cap;
    }
    (*buf)[(*len)++] = (char)c;
    (*buf)[*len] = '\0';
    return 0;
}

int main(void) {
    char *buf = NULL;
    size_t len = 0;
    size_t cap = 0;
    int ch;

    while ((ch = getchar()) != EOF) {
        if (append_char(&buf, &len, &cap, ch) != 0) {
            free(buf);
            return 1;
        }
    }

    size_t i = 0;
    while (i < len && isspace((unsigned char)buf[i])) {
        i++;
    }
    if (i < len && buf[i] == '+') {
        i++;
    }

    size_t start = i;
    while (i < len && isdigit((unsigned char)buf[i])) {
        i++;
    }

    size_t end = i;
    if (end == start) {
        printf("0\n");
        free(buf);
        return 0;
    }

    size_t z = start;
    while (z < end && buf[z] == '0') {
        z++;
    }
    if (z == end) {
        printf("0\n");
        free(buf);
        return 0;
    }

    size_t n = end - z;
    int *digits = malloc(n * sizeof(int));
    if (digits == NULL) {
        free(buf);
        return 1;
    }
    for (size_t k = 0; k < n; k++) {
        digits[k] = buf[z + k] - '0';
    }

    size_t count = 0;
    size_t alen = n;
    for (;;) {
        size_t j = 0;
        while (j < alen && digits[j] == 0) {
            j++;
        }
        if (j == alen) {
            break;
        }
        if (j > 0) {
            memmove(digits, digits + j, (alen - j) * sizeof(int));
            alen -= j;
        }

        int remainder = 0;
        for (size_t k = 0; k < alen; k++) {
            int current = remainder * 10 + digits[k];
            digits[k] = current / 2;
            remainder = current % 2;
        }
        if (remainder) {
            count++;
        }
    }

    printf("%zu\n", count);

    free(digits);
    free(buf);
    return 0;
}

