int main(void) {
    char *line = NULL;
    size_t capacity = 0;

    if (getline(&line, &capacity, stdin) == -1) {
        printf("1\n");
        free(line);
        return 0;
    }

    size_t length = strlen(line);
    if (length > 0 && line[length - 1] == '\n') {
        line[length - 1] = '\0';
        --length;
    }
    if (length > 0 && line[length - 1] == '\r') {
        line[length - 1] = '\0';
        --length;
    }

    size_t left = 0;
    size_t right = length;

    while (left < right) {
        while (left < right && line[left] == ' ') {
            ++left;
        }
        while (left < right && line[right - 1] == ' ') {
            --right;
        }
        if (left >= right) {
            break;
        }
        if (line[left] != line[right - 1]) {
            printf("0\n");
            free(line);
            return 0;
        }
        ++left;
        --right;
    }

    printf("1\n");
    free(line);
    return 0;
}

