int main(void) {
    size_t cap = 4096;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        return 1;
    }

    int c;
    while ((c = fgetc(stdin)) != EOF) {
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            if (new_cap < cap) {
                free(buf);
                return 1;
            }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                return 1;
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }
    buf[len] = '\0';

    size_t best_start = 0;
    size_t best_len = 0;
    size_t i = 0;

    while (i < len) {
        while (i < len && isspace((unsigned char)buf[i])) {
            i++;
        }
        if (i >= len) {
            break;
        }

        size_t start = i;
        while (i < len && !isspace((unsigned char)buf[i])) {
            i++;
        }

        size_t word_len = i - start;
        if (word_len > best_len) {
            best_start = start;
            best_len = word_len;
        }
    }

    if (best_len > 0) {
        fwrite(buf + best_start, 1, best_len, stdout);
    }
    putchar('\n');

    free(buf);
    return 0;
}

