#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int main(void)
{
    size_t cap = 16;
    size_t len = 1;
    unsigned char *num = malloc(cap);
    if (num == NULL) {
        return 1;
    }
    num[0] = 0;

#define GROW() do { \
        if (len == cap) { \
            cap *= 2; \
            unsigned char *tmp = realloc(num, cap); \
            if (tmp == NULL) { \
                free(num); \
                return 1; \
            } \
            num = tmp; \
        } \
    } while (0)

    int c;
    while ((c = getchar()) != EOF) {
        if (c == '\n') {
            break;
        }
        if (c == '\r' || isspace((unsigned char)c)) {
            continue;
        }
        if (!isxdigit((unsigned char)c)) {
            break;
        }

        int digit;
        if (c >= '0' && c <= '9') {
            digit = c - '0';
        } else if (c >= 'a' && c <= 'f') {
            digit = c - 'a' + 10;
        } else {
            digit = c - 'A' + 10;
        }

        /* Multiply current value by 16. */
        unsigned carry = 0;
        for (size_t i = 0; i < len; i++) {
            unsigned t = num[i] * 16u + carry;
            num[i] = (unsigned char)(t % 10u);
            carry = t / 10u;
        }
        while (carry > 0) {
            GROW();
            num[len++] = (unsigned char)(carry % 10u);
            carry /= 10u;
        }

        /* Add the new hexadecimal digit. */
        carry = (unsigned)digit;
        for (size_t i = 0; i < len && carry > 0; i++) {
            unsigned t = num[i] + carry;
            num[i] = (unsigned char)(t % 10u);
            carry = t / 10u;
        }
        while (carry > 0) {
            GROW();
            num[len++] = (unsigned char)(carry % 10u);
            carry /= 10u;
        }
    }

    /* Consume the rest of stdin. */
    while ((c = getchar()) != EOF) {
    }

    for (size_t i = len; i-- > 0; ) {
        putchar('0' + num[i]);
    }
    putchar('\n');

    free(num);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

int main(void) {
    size_t cap = 4096, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) return 1;

    for (;;) {
        if (len == cap) {
            size_t new_cap = cap * 2;
            if (new_cap < cap) { free(buf); return 1; }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) { free(buf); return 1; }
            buf = tmp;
            cap = new_cap;
        }
        size_t got = fread(buf + len, 1, cap - len, stdin);
        if (got == 0) break;
        len += got;
    }
    if (ferror(stdin)) { free(buf); return 1; }

    char *tmp = realloc(buf, len + 1);
    if (tmp == NULL) { free(buf); return 1; }
    buf = tmp;
    buf[len] = '\0';

    const char *p = buf;
    while (isspace((unsigned char)*p)) ++p;
    int negative = 0;
    if (*p == '+' || *p == '-') {
        if (*p == '-') negative = 1;
        ++p;
    }

    const char *start = p;
    while (isdigit((unsigned char)*p)) ++p;
    size_t digit_count = (size_t)(p - start);

    size_t begin = 0;
    while (begin < digit_count && start[begin] == '0') ++begin;
    size_t mag_len = digit_count - begin;

    if (mag_len == 0) {
        putchar('0');
        putchar('\n');
        free(buf);
        return 0;
    }

    int *digits = malloc(mag_len * sizeof *digits);
    if (digits == NULL) { free(buf); return 1; }
    for (size_t i = 0; i < mag_len; ++i) digits[i] = start[begin + i] - '0';

    size_t hex_cap = mag_len + 2;
    char *hex = malloc(hex_cap);
    if (hex == NULL) { free(digits); free(buf); return 1; }
    size_t hex_len = 0;
    size_t work_len = mag_len;

    while (work_len > 0) {
        unsigned remainder = 0;
        for (size_t i = 0; i < work_len; ++i) {
            unsigned current = remainder * 10u + (unsigned)digits[i];
            digits[i] = (int)(current / 16u);
            remainder = current % 16u;
        }
        size_t first_nonzero = 0;
        while (first_nonzero < work_len && digits[first_nonzero] == 0) ++first_nonzero;
        size_t new_len = work_len - first_nonzero;
        if (new_len > 0) memmove(digits, digits + first_nonzero, new_len * sizeof *digits);
        work_len = new_len;

        char c = (remainder < 10u)
                    ? (char)('0' + remainder)
                    : (char)('a' + (remainder - 10u));
        hex[hex_len++] = c;
    }

    if (negative) putchar('-');
    for (size_t i = hex_len; i > 0; --i) putchar(hex[i - 1]);
    putchar('\n');

    free(hex);
    free(digits);
    free(buf);
    return 0;
}

