#include <stdio.h>
#include <stdlib.h>

static void quicksort(int *a, int lo, int hi) {
    if (lo >= hi) return;
    int pivot = a[(lo + hi) / 2];
    int i = lo;
    int j = hi;
    while (1) {
        while (a[i] < pivot) i++;
        while (a[j] > pivot) j--;
        if (i >= j) break;
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        i++;
        j--;
    }
    quicksort(a, lo, j);
    quicksort(a, j + 1, hi);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0) return 0;
    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof(int));
        if (a == NULL) return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return 1;
        }
    }
    if (n > 0) quicksort(a, 0, n - 1);
    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
        printf("%d", a[i]);
    }
    if (n > 0) putchar('\n');
    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static void merge(ll a[], ll tmp[], size_t l, size_t m, size_t r) {
    size_t i = l, j = m, k = l;
    while (i < m && j < r) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
    }
    while (i < m) tmp[k++] = a[i++];
    while (j < r) tmp[k++] = a[j++];
    for (k = l; k < r; k++) a[k] = tmp[k];
}

static void msort(ll a[], ll tmp[], size_t l, size_t r) {
    if (r - l <= 1) return;
    size_t m = (l + r) / 2;
    msort(a, tmp, l, m);
    msort(a, tmp, m, r);
    merge(a, tmp, l, m, r);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0) return 0;
    if (n == 0) {
        printf("\n");
        return 0;
    }
    ll *a = malloc((size_t)n * sizeof(ll));
    ll *tmp = malloc((size_t)n * sizeof(ll));
    if (!a || !tmp) {
        free(a);
        free(tmp);
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%lld", &a[i]) != 1) {
            free(a);
            free(tmp);
            return 1;
        }
    }
    msort(a, tmp, 0, (size_t)n);
    for (int i = 0; i < n; i++) {
        printf("%lld", a[i]);
        if (i + 1 < n) printf(" ");
    }
    printf("\n");
    free(a);
    free(tmp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void swap_int(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

static void sift_down(int *a, size_t start, size_t end) {
    size_t root = start;
    while (2 * root + 1 < end) {
        size_t child = 2 * root + 1;
        if (child + 1 < end && a[child] < a[child + 1]) {
            child++;
        }
        if (a[root] < a[child]) {
            swap_int(&a[root], &a[child]);
            root = child;
        } else {
            break;
        }
    }
}

static void heap_sort(int *a, size_t n) {
    if (n < 2) return;

    for (size_t i = n / 2; i-- > 0; ) {
        sift_down(a, i, n);
    }

    for (size_t end = n; end > 1; end--) {
        swap_int(&a[0], &a[end - 1]);
        sift_down(a, 0, end - 1);
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            return 1;
        }
        for (int i = 0; i < n; i++) {
            if (scanf("%d", &a[i]) != 1) {
                free(a);
                return 1;
            }
        }
    }

    heap_sort(a, (size_t)n);

    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');

    free(a);
    return 0;
}

