int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            return 1;
        }
        for (int i = 0; i < n; i++) {
            if (scanf("%d", &a[i]) != 1) {
                free(a);
                return 0;
            }
        }
    }

    int x;
    if (scanf("%d", &x) != 1) {
        free(a);
        return 0;
    }

    int left = 0;
    int right = n - 1;
    int answer = -1;

    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (a[mid] == x) {
            answer = mid;
            break;
        } else if (a[mid] < x) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    printf("%d\n", answer);
    free(a);
    return 0;
}

