#include <stdio.h>

static char grid[10][10];
static int visited[10][10];

static void dfs(int r, int c) {
    if (r < 0 || r >= 10 || c < 0 || c >= 10) return;
    if (grid[r][c] != '#' || visited[r][c]) return;
    visited[r][c] = 1;
    dfs(r - 1, c);
    dfs(r + 1, c);
    dfs(r, c - 1);
    dfs(r, c + 1);
}

