} Node;

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *head = NULL;
    Node *tail = NULL;
    int count = 0;

    for (int i = 0; i < n; ++i) {
        int value;

        if (scanf("%d", &value) != 1) {
            break;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            Node *current = head;
            while (current != NULL) {
                Node *next = current->next;
                free(current);
                current = next;
            }
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (head == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }

        ++count;
    }

    Node **stack = count > 0 ? malloc((size_t)count * sizeof *stack) : NULL;
    if (count > 0 && stack == NULL) {
        Node *current = head;
        while (current != NULL) {
            Node *next = current->next;
            free(current);
            current = next;
        }
        return 1;
    }

    int top = 0;
    for (Node *current = head; current != NULL; current = current->next) {
        stack[top++] = current;
    }

    int first = 1;
    while (top > 0) {
        if (!first) {
            putchar(' ');
        }
        printf("%d", stack[--top]->value);
        first = 0;
    }
    putchar('\n');

    Node *current = head;
    while (current != NULL) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    free(stack);

    return 0;
}

