#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *left;
    struct Node *right;
} Node;

static Node *new_node(int val) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    node->val = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static void insert(Node **root, int val) {
    if (*root == NULL) {
        *root = new_node(val);
        return;
    }

    Node *cur = *root;
    while (1) {
        if (val < cur->val) {
            if (cur->left == NULL) {
                cur->left = new_node(val);
                break;
            }
            cur = cur->left;
        } else {
            if (cur->right == NULL) {
                cur->right = new_node(val);
                break;
            }
            cur = cur->right;
        }
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 0) {
        return 0;
    }

    Node *root = NULL;
    for (int i = 0; i < n; i++) {
        int val;
        if (scanf("%d", &val) != 1) {
            return 0;
        }
        insert(&root, val);
    }

    Node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            fprintf(stderr, "out of memory\n");
            return 1;
        }
    }

    Node *cur = root;
    int top = 0;
    int first = 1;

    while (cur != NULL || top > 0) {
        while (cur != NULL) {
            stack[top++] = cur;
            cur = cur->left;
        }
        cur = stack[--top];

        if (!first) {
            putchar(' ');
        }
        first = 0;
        printf("%d", cur->val);

        cur = cur->right;
    }

    putchar('\n');

    free(stack);
    return 0;
}

