#include <stdio.h>
#include <ctype.h>

int main(void) {
    int stack[65536];
    int sp = 0;
    int c;

    while ((c = getchar()) != EOF && c != '\n') {
        if (isspace((unsigned char)c)) {
            continue;
        }

        if (isdigit((unsigned char)c)) {
            stack[sp++] = c - '0';
        } else {
            if (sp < 2) {
                return 1;
            }
            int b = stack[--sp];
            int a = stack[--sp];
            int r;

            switch (c) {
                case '+':
                    r = a + b;
                    break;
                case '-':
                    r = a - b;
                    break;
                case '*':
                    r = a * b;
                    break;
                case '/':
                    if (b == 0) {
                        return 1;
                    }
                    r = a / b;
                    break;
                default:
                    return 1;
            }

            stack[sp++] = r;
        }
    }

    if (sp != 1) {
        return 1;
    }

    printf("%d\n", stack[0]);
    return 0;
}

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t capacity = 1024;
    size_t length = 0;
    char *input = malloc(capacity);
    if (input == NULL) {
        return 1;
    }

    int ch;
    while ((ch = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *tmp = realloc(input, capacity);
            if (tmp == NULL) {
                free(input);
                return 1;
            }
            input = tmp;
        }
        input[length++] = (char)ch;
    }
    input[length] = '\0';

    const char *p = input;
    while (isspace((unsigned char)*p)) {
        p++;
    }

    long long result = 0;
    int number_sign = 1;

    if (*p == '+' || *p == '-') {
        if (*p == '-') {
            number_sign = -1;
        }
        p++;
    }

    if (isdigit((unsigned char)*p)) {
        long long number = 0;
        while (isdigit((unsigned char)*p)) {
            number = number * 10 + (*p - '0');
            p++;
        }
        result += number_sign * number;
    }

    for (;;) {
        while (isspace((unsigned char)*p)) {
            p++;
        }
        if (*p == '\0' || *p == '\n') {
            break;
        }

        int operator_sign = 1;
        if (*p == '+') {
            p++;
        } else if (*p == '-') {
            operator_sign = -1;
            p++;
        } else {
            break;
        }

        while (isspace((unsigned char)*p)) {
            p++;
        }

        if (*p == '+' || *p == '-') {
            if (*p == '-') {
                operator_sign = -operator_sign;
            }
            p++;
        }

        while (isspace((unsigned char)*p)) {
            p++;
        }

        if (!isdigit((unsigned char)*p)) {
            break;
        }

        long long number = 0;
        while (isdigit((unsigned char)*p)) {
            number = number * 10 + (*p - '0');
            p++;
        }
        result += operator_sign * number;
    }

    printf("%lld\n", result);
    free(input);
    return 0;
}

#include <stdio.h>
