static int cmp_words(const void *a, const void *b) {
    const char *x = *(const char **)a;
    const char *y = *(const char **)b;
    return strcmp(x, y);
}

int main(void) {
    size_t cap = 1024;
    size_t len = 0;
    char *input = malloc(cap);
    if (input == NULL) {
        return 1;
    }

    for (;;) {
        if (len == cap) {
            cap *= 2;
            char *tmp = realloc(input, cap);
            if (tmp == NULL) {
                free(input);
                return 1;
            }
            input = tmp;
        }
        size_t got = fread(input + len, 1, cap - len, stdin);
        len += got;
        if (got == 0) {
            break;
        }
    }

    if (len == cap) {
        char *tmp = realloc(input, cap + 1);
        if (tmp == NULL) {
            free(input);
            return 1;
        }
        input = tmp;
    }
    input[len] = '\0';

    size_t wcap = 16;
    size_t wcount = 0;
    char **words = malloc(wcap * sizeof *words);
    if (words == NULL) {
        free(input);
        return 1;
    }

    char *p = input;
    while (*p != '\0') {
        while (*p != '\0' && isspace((unsigned char)*p)) {
            p++;
        }
        if (*p == '\0') {
            break;
        }
        if (wcount == wcap) {
            wcap *= 2;
            char **tmp = realloc(words, wcap * sizeof *tmp);
            if (tmp == NULL) {
                free(words);
                free(input);
                return 1;
            }
            words = tmp;
        }
        words[wcount++] = p;

        while (*p != '\0' && !isspace((unsigned char)*p)) {
            p++;
        }
        if (*p != '\0') {
            *p = '\0';
            p++;
        }
    }

    if (wcount > 0) {
        qsort(words, wcount, sizeof *words, cmp_words);
    }

    for (size_t i = 0; i < wcount; i++) {
        fputs(words[i], stdout);
        fputc('\n', stdout);
    }

    free(words);
    free(input);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int roman_value(char c) {
    switch (c) {
        case 'I': case 'i': return 1;
        case 'V': case 'v': return 5;
        case 'X': case 'x': return 10;
        case 'L': case 'l': return 50;
        case 'C': case 'c': return 100;
        case 'D': case 'd': return 500;
        case 'M': case 'm': return 1000;
        default: return 0;
    }
}

int main(void) {
    size_t capacity = 1024;
    size_t length = 0;
    char *input = malloc(capacity);
    if (input == NULL) {
        return 1;
    }

    int ch;
    while ((ch = getchar()) != EOF) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *tmp = realloc(input, capacity);
            if (tmp == NULL) {
                free(input);
                return 1;
            }
            input = tmp;
        }
        input[length++] = (char)ch;
    }
    input[length] = '\0';

    int *values = malloc((length + 1) * sizeof(int));
    if (values == NULL) {
        free(input);
        return 1;
    }

    size_t count = 0;
    for (size_t i = 0; i < length; i++) {
        int v = roman_value(input[i]);
        if (v > 0) {
            values[count++] = v;
        }
    }

    long long total = 0;
    for (size_t i = 0; i < count; i++) {
        if (i + 1 < count && values[i] < values[i + 1]) {
            total -= values[i];
        } else {
            total += values[i];
        }
    }

    printf("%lld\n", total);

    free(values);
    free(input);
    return 0;
}

