#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    int *a = calloc((size_t)n * n, sizeof *a);
    if (a == NULL) {
        return 1;
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    int num = 1;

    while (num <= n * n) {
        for (int j = left; j <= right && num <= n * n; ++j) {
            a[top * n + j] = num++;
        }
        ++top;

        for (int i = top; i <= bottom && num <= n * n; ++i) {
            a[i * n + right] = num++;
        }
        --right;

        if (top <= bottom) {
            for (int j = right; j >= left && num <= n * n; --j) {
                a[bottom * n + j] = num++;
            }
            --bottom;
        }

        if (left <= right) {
            for (int i = bottom; i >= top && num <= n * n; --i) {
                a[i * n + left] = num++;
            }
            ++left;
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (j > 0) {
                putchar(' ');
            }
            printf("%d", a[i * n + j]);
        }
        putchar('\n');
    }

    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *next_term(const char *s)
{
    size_t cap = 64;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        fprintf(stderr, "out of memory\n");
        exit(EXIT_FAILURE);
    }

    size_t slen = strlen(s);
    size_t i = 0;
    while (i < slen) {
        char c = s[i];
        size_t j = i + 1;
        while (j < slen && s[j] == c) {
            ++j;
        }
        size_t run = j - i;

        char count_buf[32];
        int count_len = snprintf(count_buf, sizeof(count_buf), "%zu", run);
        if (count_len < 0) {
            fprintf(stderr, "formatting error\n");
            free(buf);
            exit(EXIT_FAILURE);
        }

        size_t needed = len + (size_t)count_len + 2;
        if (needed > cap) {
            while (cap < needed) {
                cap *= 2;
            }
            char *tmp = realloc(buf, cap);
            if (tmp == NULL) {
                fprintf(stderr, "out of memory\n");
                free(buf);
                exit(EXIT_FAILURE);
            }
            buf = tmp;
        }

        memcpy(buf + len, count_buf, (size_t)count_len);
        len += (size_t)count_len;
        buf[len++] = c;

        i = j;
    }

    if (len + 1 > cap) {
        char *tmp = realloc(buf, len + 1);
        if (tmp == NULL) {
            fprintf(stderr, "out of memory\n");
            free(buf);
            exit(EXIT_FAILURE);
        }
        buf = tmp;
    }
    buf[len] = '\0';
    return buf;
}

int main(void)
{
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    char *term = malloc(2);
    if (term == NULL) {
        return 1;
    }
    term[0] = '1';
    term[1] = '\0';

    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            char *next = next_term(term);
            free(term);
            term = next;
        }
        puts(term);
    }

    free(term);
    return 0;
}

