/* Return the non-negative greatest common divisor of a and b. */
static long long gcd(long long a, long long b)
{
    while (b != 0) {
        long long remainder = a % b;
        a = b;
        b = remainder;
    }

    if (a < 0) {
        a = -a;
    }
    return a;
}

