#include <stdio.h>

typedef unsigned long long u64;

static u64 mulmod(u64 a, u64 b, u64 m) {
    return (u64)((__int128)a * b % m);
}

static u64 powmod(u64 a, u64 e, u64 m) {
    u64 r = 1 % m;
    a %= m;
    while (e > 0) {
        if (e & 1) r = mulmod(r, a, m);
        a = mulmod(a, a, m);
        e >>= 1;
    }
    return r;
}

static int is_prime(u64 n) {
    if (n < 2) return 0;

    static const u64 small[] = {
        2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL,
        17ULL, 19ULL, 23ULL, 29ULL, 31ULL, 37ULL
    };
    int small_count = (int)(sizeof(small) / sizeof(small[0]));

    for (int i = 0; i < small_count; i++) {
        if (n == small[i]) return 1;
        if (n % small[i] == 0) return 0;
    }

    u64 d = n - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        s++;
    }

    static const u64 bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL,
        450775ULL, 9780504ULL, 1795265022ULL
    };
    int base_count = (int)(sizeof(bases) / sizeof(bases[0]));

    for (int i = 0; i < base_count; i++) {
        u64 a = bases[i] % n;
        if (a == 0) continue;

        u64 x = powmod(a, d, n);
        if (x == 1 || x == n - 1) continue;

        int composite = 1;
        for (int r = 1; r < s; r++) {
            x = mulmod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }
        if (composite) return 0;
    }

    return 1;
}

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    if (n < 2) {
        printf("0\n");
        return 0;
    }

    printf("%d\n", is_prime((u64)n));
    return 0;
}

