#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

int main(void) {
    int c;

    /* Skip leading whitespace. */
    do {
        c = getchar();
    } while (c != EOF && isspace((unsigned char)c));

    if (c == EOF) {
        return 0;
    }

    int negative = 0;
    if (c == '-' || c == '+') {
        if (c == '-') {
            negative = 1;
        }
        c = getchar();
    }

    /* Read the digits into a dynamically grown buffer. */
    size_t capacity = 16;
    size_t length = 0;
    char *digits = malloc(capacity);
    if (digits == NULL) {
        return 1;
    }

    while (c != EOF && isdigit((unsigned char)c)) {
        if (length + 1 >= capacity) {
            capacity *= 2;
            char *temp = realloc(digits, capacity);
            if (temp == NULL) {
                free(digits);
                return 1;
            }
            digits = temp;
        }
        digits[length++] = (char)c;
        c = getchar();
    }
    digits[length] = '\0';

    if (length == 0) {
        puts("0");
        free(digits);
        return 0;
    }

    /* Reverse the digits in place. */
    for (size_t i = 0; i < length / 2; i++) {
        char temp = digits[i];
        digits[i] = digits[length - 1 - i];
        digits[length - 1 - i] = temp;
    }

    /* Remove leading zeros from the reversed result. */
    size_t start = 0;
    while (start < length - 1 && digits[start] == '0') {
        start++;
    }

    /* A value of zero is never negative. */
    if (start == length - 1 && digits[start] == '0') {
        negative = 0;
    }

    if (negative) {
        putchar('-');
    }
    for (size_t i = start; i < length; i++) {
        putchar(digits[i]);
    }
    putchar('\n');

    free(digits);
    return 0;
}

