static long long mod_mul(long long x, long long y, long long mod) {
    return (long long)((__int128)x * y % mod);
}

static long long mod_pow(long long base, long long exp, long long mod) {
    if (mod == 1) {
        return 0;
    }

    long long result = 1 % mod;
    base %= mod;
    if (base < 0) {
        base += mod;
    }

    while (exp > 0) {
        if (exp & 1LL) {
            result = mod_mul(result, base, mod);
        }
        base = mod_mul(base, base, mod);
        exp >>= 1;
    }

    return result;
}

