    if (n < 0) {
        n = -n;
    }
    if (n == 0) {
        printf("0\n");
        return 0;
    }

    unsigned long long sum = 0;

    /* Check divisor pairs (i, n / i) up to sqrt(n). */
    for (long long i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            if (i != n) {
                sum += (unsigned long long)i;
            }

            long long other = n / i;
