int main(void) {
    size_t capacity = 128;
    size_t length = 0;
    char *line = malloc(capacity);

    if (line == NULL) {
        return 1;
    }

    int character;

    /* Read one line: stop at newline or end of file. */
    while ((character = getchar()) != EOF && character != '\n') {
        if (length + 1 > capacity) {
            size_t new_capacity = capacity * 2;

            if (new_capacity < capacity) {
                free(line);
                return 1;
            }

            char *new_line = realloc(line, new_capacity);

            if (new_line == NULL) {
                free(line);
                return 1;
            }

            line = new_line;
            capacity = new_capacity;
        }

        line[length++] = (char)character;
    }

    if (ferror(stdin)) {
        free(line);
        return 1;
    }

    /* Reverse the characters in place. */
    for (size_t i = 0; i < length / 2; i++) {
        char temporary = line[i];
        line[i] = line[length - 1 - i];
        line[length - 1 - i] = temporary;
    }

    /* Write the reversed line. */
    if (fwrite(line, 1, length, stdout) != length) {
        free(line);
        return 1;
    }

    /* Preserve the original newline, if there was one. */
    if (character == '\n' && putchar('\n') == EOF) {
        free(line);
        return 1;
    }

    free(line);
    return 0;
}

