#define BASE 1000000000U

static int hex_digit_value(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return 0;
}

int main(void)
{
    char *buf = NULL;
    size_t cap = 0;
    size_t len = 0;
    int c;

    while ((c = getchar()) != EOF && c != '\n') {
        if (c == '\r') {
            int next = getchar();
            if (next != EOF && next != '\n') {
                ungetc(next, stdin);
            }
            break;
        }

        if (len + 1 > cap) {
            size_t new_cap = cap ? cap * 2 : 256;
            while (new_cap < len + 1) {
                new_cap *= 2;
            }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                free(buf);
                fprintf(stderr, "out of memory\n");
                return 1;
            }
            buf = tmp;
            cap = new_cap;
        }

        buf[len++] = (char)c;
    }

    if (buf == NULL) {
        buf = calloc(1, 1);
        if (buf == NULL) {
            fprintf(stderr, "out of memory\n");
            return 1;
        }
    } else {
        buf[len] = '\0';
    }

    size_t start = 0;
    while (start < len && isspace((unsigned char)buf[start])) {
        start++;
    }

    size_t end = len;
    while (end > start && isspace((unsigned char)buf[end - 1])) {
        end--;
    }

    if (end - start >= 2 && buf[start] == '0' &&
        (buf[start + 1] == 'x' || buf[start + 1] == 'X')) {
        start += 2;
    }

    for (size_t i = start; i < end; i++) {
        if (!isxdigit((unsigned char)buf[i])) {
            fprintf(stderr, "invalid hexadecimal input\n");
            free(buf);
            return 1;
        }
    }

    size_t digit_count = end - start;
    if (digit_count == 0) {
        puts("0");
        free(buf);
        return 0;
    }

    uint32_t *chunks = calloc(digit_count + 2, sizeof *chunks);
    if (chunks == NULL) {
        free(buf);
        fprintf(stderr, "out of memory\n");
        return 1;
    }

    size_t chunk_count = 1;
    chunks[0] = 0;

    for (size_t i = start; i < end; i++) {
        uint32_t carry = (uint32_t)hex_digit_value(buf[i]);

        for (size_t j = 0; j < chunk_count; j++) {
            uint64_t current = (uint64_t)chunks[j] * 16 + carry;
            chunks[j] = (uint32_t)(current % BASE);
            carry = (uint32_t)(current / BASE);
        }

        while (carry != 0) {
            chunks[chunk_count++] = carry % BASE;
            carry /= BASE;
        }
    }

    printf("%u", chunks[chunk_count - 1]);
    if (chunk_count > 1) {
        for (size_t j = chunk_count - 2; ; j--) {
            printf("%09u", chunks[j]);
            if (j == 0) {
                break;
            }
        }
    }
    putchar('\n');

    free(chunks);
    free(buf);
    return 0;
}

