/* Read n integers, sort ascending with selection sort, print space-separated. */
int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        return 0; /* no valid input */
    }
    if (n < 0) {
        return 0; /* invalid count */
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            return 1; /* allocation failed */
        }
        for (int i = 0; i < n; i++) {
            if (scanf("%d", &a[i]) != 1) {
                free(a);
                return 1; /* bad input */
            }
        }
    }

    /* Selection sort: ascending. */
    for (int i = 0; i < n - 1; i++) {
        int min_index = i;
        for (int j = i + 1; j < n; j++) {
            if (a[j] < a[min_index]) {
                min_index = j;
            }
        }
        if (min_index != i) {
            int tmp = a[i];
            a[i] = a[min_index];
            a[min_index] = tmp;
        }
    }

    /* Print space-separated. */
