#include <stdlib.h>

static void swap(int *x, int *y) {
    int tmp = *x;
    *x = *y;
    *y = tmp;
}

static void quicksort(int *a, int low, int high) {
    if (low >= high) {
        return;
    }

    int pivot = a[low + (high - low) / 2];
    int i = low - 1;
    int j = high + 1;

    while (1) {
        do {
            i++;
        } while (a[i] < pivot);

        do {
            j--;
        } while (a[j] > pivot);

        if (i >= j) {
            quicksort(a, low, j);
            quicksort(a, j + 1, high);
            return;
        }

        swap(&a[i], &a[j]);
    }
}

