#include <stdio.h>
#include <stdlib.h>

static void sift_down(int *a, size_t n, size_t i)
{
    while (2 * i + 1 < n) {
        size_t left = 2 * i + 1;
        size_t right = left + 1;
        size_t largest = i;

        if (a[left] > a[largest]) {
            largest = left;
        }
        if (right < n && a[right] > a[largest]) {
            largest = right;
        }
        if (largest == i) {
            break;
        }

        int tmp = a[i];
        a[i] = a[largest];
        a[largest] = tmp;

        i = largest;
    }
}

static void heap_sort(int *a, size_t n)
{
    if (n < 2) {
        return;
    }

    for (size_t i = n / 2; i > 0; --i) {
        sift_down(a, n, i - 1);
    }

    for (size_t end = n; end > 1; --end) {
        int tmp = a[0];
        a[0] = a[end - 1];
        a[end - 1] = tmp;
        sift_down(a, end - 1, 0);
    }
}

