    if (scanf("%ld", &n) != 1) {
        return 0;
    }
    if (n < 0) {
        fprintf(stderr, "n must be non-negative\n");
        return 1;
    }

    int *arr = NULL;
    size_t size = 0;
    size_t cap = 0;
    long long sum = 0;

    for (long i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            fprintf(stderr, "expected an integer (missing value %ld of %ld)\n",
                    i + 1, n);
            free(arr);
            return 1;
        }

        if (size == cap) {
            size_t newcap = (cap == 0) ? 1 : cap * 2;
            if (newcap < cap || newcap > SIZE_MAX / sizeof(int)) {
                fprintf(stderr, "array capacity overflow\n");
                free(arr);
                return 1;
            }
            int *tmp = realloc(arr, newcap * sizeof(int));
            if (!tmp) {
                perror("realloc");
                free(arr);
                return 1;
            }
            arr = tmp;
            cap = newcap;
        }

        arr[size] = x;
        size++;
        sum += x;
    }

    printf("%lld\n", sum);
    free(arr);
    return 0;
}

