#include <stdio.h>

struct Complex {
    double re;
    double im;
};

int main(void) {
    struct Complex a, b, product;

    if (scanf("%lf %lf %lf %lf", &a.re, &a.im, &b.re, &b.im) != 4) {
        return 1;
    }

    product.re = a.re * b.re - a.im * b.im;
    product.im = a.re * b.im + a.im * b.re;

    printf("%.6f %.6f\n", product.re, product.im);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        return 1;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            free_list(head);
            return 1;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            free_list(head);
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (head == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }

    Node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            free_list(head);
            return 1;
        }
    }

    Node *current = head;
    int top = 0;
    while (current != NULL) {
        stack[top++] = current;
        current = current->next;
    }

    int first = 1;
    while (top > 0) {
        Node *node = stack[--top];
        if (!first) {
            putchar(' ');
        }
        printf("%d", node->value);
        first = 0;
    }
    putchar('\n');

    free_list(head);
    free(stack);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 0) {
        fprintf(stderr, "n must be non-negative\n");
        return 1;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < n; i++) {
        int value;

        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "expected %d integers\n", n);
            free_list(head);
            return 1;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            perror("malloc");
            free_list(head);
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (tail == NULL) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }
    }

    /* Reverse the list in place by relinking pointers. */
    Node *previous = NULL;
    Node *current = head;
    while (current != NULL) {
        Node *next = current->next;
        current->next = previous;
        previous = current;
        current = next;
    }
    head = previous;

    /* Print the reversed list. */
    for (Node *node = head; node != NULL; node = node->next) {
        printf("%d", node->value);
        if (node->next != NULL) {
            putchar(' ');
        }
    }
    putchar('\n');

    free_list(head);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

static Node *create_node(int value) {
    Node *node = malloc(sizeof *node);
    if (node == NULL) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static Node *insert(Node *root, int value) {
    Node *new_node = create_node(value);

    if (root == NULL) {
        return new_node;
    }

    Node *current = root;
    Node *parent = NULL;

    while (current != NULL) {
        parent = current;
        if (value < current->value) {
            current = current->left;
        } else {
            current = current->right;
        }
    }

    if (value < parent->value) {
        parent->left = new_node;
    } else {
        parent->right = new_node;
    }

    return root;
}

static void inorder_iterative(Node *root, Node **stack, int stack_size) {
    int top = -1;
    Node *current = root;

    while (current != NULL || top >= 0) {
        while (current != NULL) {
            stack[++top] = current;
            current = current->left;
        }

        current = stack[top--];
        printf("%d\n", current->value);
        current = current->right;
    }

    (void)stack_size;
}

static void free_tree(Node *root) {
    if (root == NULL) {
        return;
    }
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "Failed to read n\n");
        return 1;
    }

    if (n < 0) {
        fprintf(stderr, "n must be non-negative\n");
        return 1;
    }

    Node *root = NULL;

    for (int i = 0; i < n; ++i) {
        int value;

        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "Failed to read integer %d\n", i);
            free_tree(root);
            return 1;
        }

        root = insert(root, value);
    }

    Node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            fprintf(stderr, "Out of memory\n");
            free_tree(root);
            return 1;
        }
    }

    inorder_iterative(root, stack, n);

    free(stack);
    free_tree(root);
    return 0;
}

