    int top = -1;
    char command;

    while (scanf(" %c", &command) == 1) {
        if (command == 'p') {
            int value;
            if (scanf("%d", &value) != 1) {
                fprintf(stderr, "missing number after p\n");
                return 1;
            }
            if (top == 99) {
                fprintf(stderr, "stack overflow\n");
            } else {
                stack[++top] = value;
            }
        } else if (command == 'o') {
            if (top < 0) {
                fprintf(stderr, "stack underflow\n");
