            }
        } else if (command == 'q') {
            break;
        }
    }

    return 0;
}

#include <stdio.h>

#define CAPACITY 100

int main(void) {
    int queue[CAPACITY];
    int head = 0;
    int tail = 0;
    int count = 0;
    char command;

    while (scanf(" %c", &command) == 1) {
        if (command == 'e') {
            int value;
            if (scanf("%d", &value) != 1) {
                break;
            }
            if (count < CAPACITY) {
                queue[tail] = value;
                tail = (tail + 1) % CAPACITY;
                ++count;
            }
        } else if (command == 'd') {
            if (count > 0) {
                printf("%d\n", queue[head]);
                head = (head + 1) % CAPACITY;
                --count;
            }
        } else if (command == 'q') {
            break;
        }
    }

    return 0;
}

