#include <stdio.h>
#include <ctype.h>

#define STACK_SIZE 100

int main(void) {
    int stack[STACK_SIZE];
    size_t top = 0;
    int c;

    while ((c = getchar()) != EOF) {
        if (isspace((unsigned char)c)) {
            continue;
        }

        if (isdigit((unsigned char)c)) {
            if (top == STACK_SIZE) {
                fprintf(stderr, "Stack overflow\n");
                return 1;
            }
            stack[top++] = c - '0';
        } else if (c == '+' || c == '-' || c == '*' || c == '/') {
            if (top < 2) {
                fprintf(stderr, "Not enough operands\n");
                return 1;
            }

            int right = stack[--top];
            int left = stack[--top];
            int result;

            switch (c) {
                case '+':
                    result = left + right;
                    break;
                case '-':
                    result = left - right;
                    break;
                case '*':
                    result = left * right;
                    break;
                case '/':
                    if (right == 0) {
                        fprintf(stderr, "Division by zero\n");
                        return 1;
                    }
                    result = left / right;
                    break;
                default:
                    result = 0;
                    break;
            }

            stack[top++] = result;
        } else {
            fprintf(stderr, "Invalid character: %c\n", c);
            return 1;
        }
    }

    if (top != 1) {
        fprintf(stderr, "Invalid RPN expression\n");
        return 1;
    }

    printf("%d\n", stack[0]);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long total = 0;
    long long number = 0;
    int has_number = 0;
    int binary_sign = 1;   /* +1 or -1 for the next complete number */
    int unary_sign = 1;    /* handles a leading '-' on a number */
    int c;

    while ((c = getchar()) != EOF && c != '\n') {
        if (c == ' ' || c == '\t' || c == '\r' || c == '\f' || c == '\v') {
            continue;
        }

        if (c >= '0' && c <= '9') {
            number = number * 10 + (c - '0');
            has_number = 1;
        } else if (c == '+' || c == '-') {
            if (has_number) {
                total += binary_sign * unary_sign * number;
                number = 0;
                has_number = 0;
                unary_sign = 1;
                binary_sign = (c == '+') ? 1 : -1;
            } else {
                if (c == '-') {
                    unary_sign = -unary_sign;
                }
            }
        } else {
            fprintf(stderr, "Invalid character in input\n");
            return 1;
        }
    }

    if (has_number) {
        total += binary_sign * unary_sign * number;
    }

    printf("%lld\n", total);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *read_line(void) {
    size_t capacity = 128;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (buffer == NULL) {
        return NULL;
    }

    int c;
    while ((c = getchar()) != EOF && c != '\n') {
        if (length + 1 >= capacity) {
            if (capacity > ((size_t)-1) / 2) {
                free(buffer);
                return NULL;
            }
            capacity *= 2;
            char *new_buffer = realloc(buffer, capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
        }
        buffer[length++] = (char)c;
    }

    if (c == EOF && length == 0) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

static int compare_words(const void *left, const void *right) {
    const char *const *a = left;
    const char *const *b = right;
    return strcmp(*a, *b);
}

int main(void) {
    char *line = read_line();
    if (line == NULL) {
        return 0;
    }

    size_t count = 0;
    size_t capacity = 0;
    char **words = NULL;
    char *word = strtok(line, " \t\r\f\v");

    while (word != NULL) {
        if (count == capacity) {
            size_t new_capacity = capacity == 0 ? 8 : capacity * 2;
            char **new_words = realloc(words, new_capacity * sizeof *new_words);
            if (new_words == NULL) {
                free(words);
                free(line);
                return 1;
            }
            words = new_words;
            capacity = new_capacity;
        }
        words[count++] = word;
        word = strtok(NULL, " \t\r\f\v");
    }

    qsort(words, count, sizeof *words, compare_words);

    for (size_t i = 0; i < count; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }
    putchar('\n');

    free(words);
    free(line);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

static int roman_digit_value(char c)
{
    switch (toupper((unsigned char)c)) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

int main(void)
{
    char text[1024];

    if (scanf("%1023s", text) != 1) {
        return 0;
    }

    long long value = 0;
    size_t i = 0;

    while (text[i] != '\0') {
        int current = roman_digit_value(text[i]);
        if (current < 0) {
            fprintf(stderr, "Invalid Roman numeral: %c\n", text[i]);
            return 1;
        }

        if (text[i + 1] != '\0') {
            int next = roman_digit_value(text[i + 1]);
            if (next < 0) {
                fprintf(stderr, "Invalid Roman numeral: %c\n", text[i + 1]);
                return 1;
            }
            if (current < next) {
                value -= current;
            } else {
                value += current;
            }
        } else {
            value += current;
        }

        ++i;
    }

    printf("%lld\n", value);
    return 0;
}

