#include <stdio.h>
#include <limits.h>

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0) {
        fprintf(stderr, "Please enter a non-negative integer.\n");
        return 1;
    }

    for (int row = 0; row < n; ++row) {
        for (int space = 0; space < n - row - 1; ++space) {
            putchar(' ');
        }

        unsigned long long value = 1ULL;

        for (int k = 0; k <= row; ++k) {
            if (k > 0) {
                putchar(' ');
            }

            printf("%llu", value);

            if (k < row) {
                unsigned long long factor = (unsigned long long)(row - k);

                if (factor > 0 && value > ULLONG_MAX / factor) {
                    fprintf(stderr, "Pascal's triangle value is too large.\n");
                    return 1;
                }

                value = value * factor / (unsigned long long)(k + 1);
            }
        }

        putchar('\n');
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;

    if (scanf("%d", &n) != 1 || n <= 0) {
        return 0;
    }

    int **matrix = malloc((size_t)n * sizeof *matrix);
    if (matrix == NULL) {
        return 1;
    }

    for (int i = 0; i < n; i++) {
        matrix[i] = malloc((size_t)n * sizeof *matrix[i]);
        if (matrix[i] == NULL) {
            return 1;
        }
    }

    int top = 0, bottom = n - 1;
    int left = 0, right = n - 1;
    int value = 1;

    while (top <= bottom && left <= right) {
        for (int j = left; j <= right; j++) {
            matrix[top][j] = value++;
        }
        top++;

        for (int i = top; i <= bottom; i++) {
            matrix[i][right] = value++;
        }
        right--;

        if (top <= bottom) {
            for (int j = right; j >= left; j--) {
                matrix[bottom][j] = value++;
            }
            bottom--;
        }

        if (left <= right) {
            for (int i = bottom; i >= top; i--) {
                matrix[i][left] = value++;
            }
            left++;
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (j > 0) {
                putchar(' ');
            }
            printf("%d", matrix[i][j]);
        }
        putchar('\n');
    }

    for (int i = 0; i < n; i++) {
        free(matrix[i]);
    }
    free(matrix);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void append_char(char **s, size_t *len, size_t *cap, char c)
{
    if (*len + 1 >= *cap) {
        size_t new_cap = *cap ? *cap * 2 : 16;
        while (new_cap <= *len + 1) {
            new_cap *= 2;
        }
        char *tmp = realloc(*s, new_cap);
        if (tmp == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
        *s = tmp;
        *cap = new_cap;
    }
    (*s)[(*len)++] = c;
    (*s)[*len] = '\0';
}

static char *next_term(const char *s)
{
    size_t len = strlen(s);
    char *result = malloc(1);
    if (result == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    result[0] = '\0';

    size_t result_len = 0;
    size_t result_cap = 1;

    size_t i = 0;
    while (i < len) {
        size_t j = i;
        while (j < len && s[j] == s[i]) {
            j++;
        }

        size_t count = j - i;
        char count_text[32];
        int count_digits = snprintf(count_text, sizeof(count_text), "%zu", count);
        if (count_digits < 0) {
            perror("snprintf");
            exit(EXIT_FAILURE);
        }

        for (int k = 0; k < count_digits; k++) {
            append_char(&result, &result_len, &result_cap, count_text[k]);
        }
        append_char(&result, &result_len, &result_cap, s[i]);

        i = j;
    }

    return result;
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n <= 0) {
        return 0;
    }

    char *term = malloc(2);
    if (term == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }
    term[0] = '1';
    term[1] = '\0';

    for (int i = 0; i < n; i++) {
        puts(term);

        if (i < n - 1) {
            char *next = next_term(term);
            free(term);
            term = next;
        }
    }

    free(term);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *read_one_line(void)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int ch;
    while ((ch = fgetc(stdin)) != EOF && ch != '\n') {
        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            if (new_capacity <= capacity) {
                free(buffer);
                return NULL;
            }

            char *new_buffer = realloc(buffer, new_capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }

            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)ch;
    }

    if (ch == EOF && length == 0) {
        free(buffer);
        return NULL;
    }

    buffer[length] = '\0';
    return buffer;
}

int main(void)
{
    char *line = read_one_line();
    if (line == NULL) {
        return 0;
    }

    int counts[256] = {0};
    int first_positions[256];

    for (int i = 0; i < 256; i++) {
        first_positions[i] = -1;
    }

    size_t length = strlen(line);
    for (size_t i = 0; i < length; i++) {
        unsigned char ch = (unsigned char)line[i];
        if (first_positions[ch] == -1) {
            first_positions[ch] = (int)i;
        }
        counts[ch]++;
    }

    int found = 0;
    unsigned char best_char = 0;
    int best_count = 0;
    int best_first_position = 0;

    for (int value = 0; value < 256; value++) {
        if (counts[value] == 0) {
            continue;
        }

        if (!found ||
            counts[value] > best_count ||
            (counts[value] == best_count &&
             first_positions[value] < best_first_position)) {
            found = 1;
            best_char = (unsigned char)value;
            best_count = counts[value];
            best_first_position = first_positions[value];
        }
    }

    if (found) {
        printf("%c %d\n", (char)best_char, best_count);
    }

    free(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int absolute(int x)
{
    return x < 0 ? -x : x;
}

static int square(int x)
{
    return x * x;
}

static int negate(int x)
{
    return -x;
}

int main(void)
{
    char command;
    int value;
    int (*transform)(int) = NULL;

    if (scanf(" %c", &command) != 1) {
        fprintf(stderr, "Missing command character.\n");
        return EXIT_FAILURE;
    }

    switch (command) {
        case 'a':
            transform = absolute;
            break;
        case 's':
            transform = square;
            break;
        case 'n':
            transform = negate;
            break;
        default:
            fprintf(stderr, "Unknown command: %c\n", command);
            return EXIT_FAILURE;
    }

    while (scanf("%d", &value) == 1) {
        printf("%d\n", transform(value));
    }

    if (ferror(stdin)) {
        fprintf(stderr, "Input read error.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

