    if (scanf("%lld %lld", &a, &b) != 2) {
        fprintf(stderr, "error: expected two integers\n");
        return EXIT_FAILURE;
    }

    /* Reject any additional non-whitespace input. */
    {
        char extra;
        if (scanf(" %c", &extra) == 1) {
            fprintf(stderr, "error: unexpected extra input\n");
            return EXIT_FAILURE;
        }
    }

    /* Convert to unsigned absolute values without signed overflow. */
    unsigned long long ua = (a < 0) ? (0ULL - (unsigned long long)a)
                                    : (unsigned long long)a;
    unsigned long long ub = (b < 0) ? (0ULL - (unsigned long long)b)
                                    : (unsigned long long)b;

    printf("%llu\n", gcd_ull(ua, ub));
    return EXIT_SUCCESS;
}

