static unsigned long long mulmod(unsigned long long a, unsigned long long b, unsigned long long m) {
    return (unsigned __int128)a * b % m;
}

static unsigned long long powmod(unsigned long long a, unsigned long long e, unsigned long long m) {
    unsigned long long r = 1 % m;
    a %= m;
    while (e > 0) {
        if (e & 1ULL) r = mulmod(r, a, m);
        a = mulmod(a, a, m);
        e >>= 1ULL;
    }
    return r;
}

static int is_prime_ull(unsigned long long n) {
    if (n < 2ULL) return 0;

    static const unsigned long long small_primes[] = {
        2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL,
        19ULL, 23ULL, 29ULL, 31ULL, 37ULL
    };
    for (size_t i = 0; i < sizeof(small_primes) / sizeof(small_primes[0]); ++i) {
        if (n == small_primes[i]) return 1;
        if (n % small_primes[i] == 0ULL) return 0;
    }

    unsigned long long d = n - 1ULL;
    int s = 0;
    while ((d & 1ULL) == 0ULL) {
        d >>= 1ULL;
        ++s;
    }

    static const unsigned long long bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL,
        9780504ULL, 1795265022ULL
    };

    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        unsigned long long a = bases[i] % n;
        if (a == 0ULL) continue;

        unsigned long long x = powmod(a, d, n);
        if (x == 1ULL || x == n - 1ULL) continue;

        int composite = 1;
        for (int r = 1; r < s; ++r) {
            x = mulmod(x, x, n);
            if (x == n - 1ULL) {
                composite = 0;
                break;
            }
        }
        if (composite) return 0;
    }
    return 1;
}

int main(void) {
    char buf[256];

    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        puts("0");
        return 0;
    }

    if (strchr(buf, '\n') == NULL && !feof(stdin)) {
        puts("0");
        return 0;
    }

    char *p = buf;
    while (isspace((unsigned char)*p)) ++p;

    int negative = 0;
    if (*p == '-') {
        negative = 1;
        ++p;
    } else if (*p == '+') {
        ++p;
    }

    char *end = NULL;
    errno = 0;
    unsigned long long value = strtoull(p, &end, 10);

    if (errno != 0) {
        puts("0");
        return 0;
    }

    while (isspace((unsigned char)*end)) ++end;
    if (*end != '\0') {
        puts("0");
        return 0;
    }

    if (negative) {
        puts("0");
        return 0;
    }

    printf("%d\n", is_prime_ull(value));
    return 0;
}

