#include <stdio.h>
#include <ctype.h>

#define MAX_TOKEN 1024

int main(void)
{
    char token[MAX_TOKEN + 1];
    size_t len = 0;
    int c;

    do {
        c = getchar();
        if (c == EOF) {
            fprintf(stderr, "error: no input\n");
            return 1;
        }
    } while (isspace((unsigned char)c));

    if (c == '+' || c == '-') {
        if (len + 1 >= sizeof token) {
            fprintf(stderr, "error: input too large\n");
            return 1;
        }
        token[len++] = (char)c;
        c = getchar();
    }

    while (isdigit((unsigned char)c)) {
        if (len + 1 >= sizeof token) {
            fprintf(stderr, "error: input too large\n");
            return 1;
        }
        token[len++] = (char)c;
        c = getchar();
    }

    if (len == 0 || (len == 1 && (token[0] == '+' || token[0] == '-'))) {
        fprintf(stderr, "error: invalid integer\n");
        return 1;
    }

    while (c != EOF) {
        if (!isspace((unsigned char)c)) {
            fprintf(stderr, "error: unexpected trailing input\n");
            return 1;
        }
        c = getchar();
    }

    token[len] = '\0';

    size_t start = (token[0] == '+' || token[0] == '-') ? 1 : 0;
    size_t i = start;
    while (i < len && token[i] == '0') {
        ++i;
    }

    int all_zero = (i == len);
    size_t revlen = len - i;

    char rev[MAX_TOKEN + 1];
    for (size_t j = 0; j < revlen; ++j) {
        rev[j] = token[len - 1 - j];
    }
    rev[revlen] = '\0';

    size_t k = 0;
    while (k < revlen && rev[k] == '0') {
        ++k;
    }

    if (all_zero || k == revlen) {
        puts("0");
    } else {
        if (token[0] == '-' && !all_zero) {
            putchar('-');
        }
        fputs(rev + k, stdout);
        putchar('\n');
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
