#define MAX_INPUT (1U << 20)

static void fail(const char *msg)
{
    fprintf(stderr, "error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int main(void)
{
    size_t cap = 1024;
    size_t len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) {
        fail("out of memory");
    }

    int c;
    while ((c = fgetc(stdin)) != EOF) {
        if (len >= MAX_INPUT) {
            fail("input too large");
        }
        if (len + 1 >= cap) {
            size_t new_cap = cap * 2;
            if (new_cap < cap || new_cap > MAX_INPUT + 1) {
                new_cap = MAX_INPUT + 1;
            }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                fail("out of memory");
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }

    if (ferror(stdin)) {
        fail("read error");
    }

    buf[len] = '\0';
    if (memchr(buf, '\0', len) != NULL) {
        fail("invalid input");
    }

    char *p = buf;
    while (isspace((unsigned char)*p)) {
        ++p;
    }

    if (*p == '-') {
        fail("negative integers are not supported");
    }
    if (*p == '+') {
        ++p;
    }
    if (!isdigit((unsigned char)*p)) {
        fail("expected an integer");
    }

    char *end = NULL;
    errno = 0;
    unsigned long long value = strtoull(p, &end, 10);
    if (errno == ERANGE) {
        fail("integer out of range");
    }
    if (end == p) {
        fail("expected an integer");
    }

    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        fail("trailing data after integer");
    }

    char out[sizeof(value) * CHAR_BIT + 2];
    size_t oi = 0;

    if (value == 0) {
        out[oi++] = '0';
    } else {
        int started = 0;
        for (int i = (int)(sizeof(value) * CHAR_BIT) - 1; i >= 0; --i) {
            if ((value >> i) & 1ULL) {
                started = 1;
                out[oi++] = '1';
            } else if (started) {
                out[oi++] = '0';
            }
        }
    }

    out[oi++] = '\n';
    out[oi] = '\0';

    if (fputs(out, stdout) == EOF || fflush(stdout) != 0) {
        fail("write error");
    }

    free(buf);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

#define INPUT_BUFFER_SIZE 256

static int parse_unsigned(const char *text, unsigned long long *value)
{
    const char *p = text;

    while (*p == ' ' || *p == '\t' || *p == '\n' ||
           *p == '\r' || *p == '\f' || *p == '\v') {
        ++p;
    }

    if (*p == '-') {
        return 0;
    }
    if (*p == '+') {
        ++p;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long parsed = strtoull(p, &end, 10);

    if (errno == ERANGE || end == p) {
        return 0;
    }

    while (*end == ' ' || *end == '\t' || *end == '\n' ||
           *end == '\r' || *end == '\f' || *end == '\v') {
        ++end;
    }

    if (*end != '\0') {
        return 0;
    }

    *value = parsed;
    return 1;
}

int main(void)
{
    char buffer[INPUT_BUFFER_SIZE];

    if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
        fprintf(stderr, "error: no input provided\n");
        return 1;
    }

    size_t length = strlen(buffer);
    if (length == sizeof(buffer) - 1 && buffer[length - 1] != '\n') {
        fprintf(stderr, "error: input is too long\n");
        return 1;
    }

    unsigned long long n;
    if (!parse_unsigned(buffer, &n)) {
        fprintf(stderr, "error: invalid non-negative integer\n");
        return 1;
    }

    int c;
    while ((c = getchar()) != EOF) {
        if (!(c == ' ' || c == '\t' || c == '\n' ||
              c == '\r' || c == '\f' || c == '\v')) {
            fprintf(stderr, "error: unexpected trailing input\n");
            return 1;
        }
    }

    if (ferror(stdin)) {
        fprintf(stderr, "error: failed while reading input\n");
        return 1;
    }

    unsigned count = 0;
    unsigned long long x = n;

    while (x != 0ULL) {
        count += (unsigned)(x & 1ULL);
        x >>= 1;
    }

    printf("%u\n", count);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static long long mod_pow(long long a, long long b, long long m) {
    long long result = 1 % m;
    long long base = ((a % m) + m) % m;

    while (b > 0) {
        if (b & 1) {
            result = (result * base) % m;
        }
        base = (base * base) % m;
        b >>= 1;
    }

    return result;
}

int main(void) {
    long long a, b, m;
    const long long LIMIT = 1000000000LL;

    if (scanf("%lld %lld %lld", &a, &b, &m) != 3) {
        fprintf(stderr, "error: expected three integers\n");
        return 1;
    }

    if (m <= 0 || m > LIMIT) {
        fprintf(stderr, "error: m must be in [1, %lld]\n", LIMIT);
        return 1;
    }
    if (b < 0 || b > LIMIT) {
        fprintf(stderr, "error: b must be in [0, %lld]\n", LIMIT);
        return 1;
    }
    if (a < -LIMIT || a > LIMIT) {
        fprintf(stderr, "error: a must be in [-%lld, %lld]\n", LIMIT, LIMIT);
        return 1;
    }

    printf("%lld\n", mod_pow(a, b, m));
    return 0;
}

