#define MAX_INPUT 1024

static int is_perfect_square_ull(unsigned long long n)
{
    if (n == 0ULL) {
        return 1;
    }

    unsigned long long lo = 1ULL;
    unsigned long long hi = 1ULL << 32;
    unsigned long long root = 0ULL;

    while (lo <= hi) {
        unsigned long long mid = lo + (hi - lo) / 2ULL;

        /* mid * mid <= n, without overflowing mid * mid */
        if (mid <= n / mid) {
            root = mid;
            lo = mid + 1ULL;
        } else {
            hi = mid - 1ULL;
        }
    }

    return root * root == n;
}

int main(void)
{
    char buf[MAX_INPUT];
    size_t total = 0;
    int c;

    while ((c = getchar()) != EOF) {
        if (total + 1 >= MAX_INPUT) {
            fprintf(stderr, "error: input too large\n");
            return 1;
        }
        buf[total++] = (char)c;
    }
    buf[total] = '\0';

    char *p = buf;
    while (isspace((unsigned char)*p)) {
        ++p;
    }

    int negative = 0;
    if (*p == '+' || *p == '-') {
        negative = (*p == '-');
        ++p;
    }

    if (!isdigit((unsigned char)*p)) {
        fprintf(stderr, "error: invalid integer input\n");
        return 1;
    }

    unsigned long long value = 0ULL;
    int digit_count = 0;

    while (isdigit((unsigned char)*p)) {
        int digit = *p - '0';

        if (value > (ULLONG_MAX - (unsigned long long)digit) / 10ULL) {
            fprintf(stderr, "error: integer out of range\n");
            return 1;
        }

        value = value * 10ULL + (unsigned long long)digit;
        ++p;
        ++digit_count;

        if (digit_count > 20) {
            fprintf(stderr, "error: integer out of range\n");
            return 1;
        }
    }

    while (isspace((unsigned char)*p)) {
        ++p;
    }

    if (*p != '\0') {
        fprintf(stderr, "error: unexpected trailing input\n");
        return 1;
    }

    int result;
    if (value == 0ULL) {
        result = 1;
    } else if (negative) {
        result = 0;
    } else {
        result = is_perfect_square_ull(value);
    }

    printf("%d\n", result);
    return 0;
}

