static int parse_nonnegative_integer(const char *s, unsigned long long *value)
{
    if (s == NULL || s[0] == '\0' || s[0] == '-') {
        return 0;
    }

    errno = 0;
    char *end = NULL;
    unsigned long long parsed = strtoull(s, &end, 10);

    if (errno == ERANGE || end == s || *end != '\0') {
        return 0;
    }

    *value = parsed;
    return 1;
}

