static int grow_buffer(char **buffer, size_t *capacity)
{
    if (*capacity > SIZE_MAX / 2) {
        return 0;
    }

    size_t new_capacity = *capacity * 2;
    if (new_capacity < *capacity) {
        return 0;
    }

    char *tmp = realloc(*buffer, new_capacity);
    if (tmp == NULL) {
        return 0;
    }

    *buffer = tmp;
    *capacity = new_capacity;
    return 1;
}

static char *read_one_line(void)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);
    if (buffer == NULL) {
        return NULL;
    }

    int ch;
    while ((ch = fgetc(stdin)) != EOF && ch != '\n') {
        if (length + 1 >= capacity) {
            if (!grow_buffer(&buffer, &capacity)) {
                free(buffer);
                return NULL;
            }
        }
        buffer[length++] = (char)ch;
    }

    if (ch == '\n') {
        if (length + 1 >= capacity) {
            if (!grow_buffer(&buffer, &capacity)) {
                free(buffer);
                return NULL;
            }
        }
        buffer[length++] = '\n';
    }

    if (length == 0 && ch == EOF) {
        free(buffer);
        return NULL;
    }

    if (length + 1 >= capacity) {
        if (!grow_buffer(&buffer, &capacity)) {
            free(buffer);
            return NULL;
        }
    }
    buffer[length] = '\0';
    return buffer;
}

int main(void)
{
    char *line = read_one_line();
    if (line == NULL) {
        if (ferror(stdin)) {
            perror("fgetc");
            return EXIT_FAILURE;
        }
        return EXIT_SUCCESS;
    }

    for (size_t i = 0; line[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)line[i];
        if (c >= 'a' && c <= 'z') {
            line[i] = (char)((c == 'z') ? 'a' : c + 1);
        }
    }

    if (fputs(line, stdout) == EOF) {
        perror("fputs");
        free(line);
        return EXIT_FAILURE;
    }

    free(line);
    return EXIT_SUCCESS;
}

