static int append_char(char **buf, size_t *len, size_t *cap, char ch, size_t max_word)
{
    if (*len + 1 > max_word) {
        return -1;
    }
    if (*len + 1 > *cap) {
        size_t newcap = *cap ? *cap * 2 : 64;
        if (newcap < *cap) {
            return -1;
        }
        while (newcap < *len + 1) {
            if (newcap > max_word + 1) {
                return -1;
            }
            newcap *= 2;
            if (newcap < *len + 1) {
                return -1;
            }
        }
        if (newcap > max_word + 1) {
            return -1;
        }
        char *tmp = realloc(*buf, newcap);
        if (!tmp) {
            return -1;
        }
        *buf = tmp;
        *cap = newcap;
    }
    (*buf)[(*len)++] = ch;
    (*buf)[*len] = '\0';
    return 0;
}

