{
    int counts[26] = {0};
    size_t length = 0;
    int c;
    int saw_newline = 0;

    while ((c = getchar()) != EOF) {
        if (c == '\n') {
            saw_newline = 1;
            break;
        }

        if (length >= MAX_LINE_LENGTH) {
            fprintf(stderr, "error: input line exceeds maximum length\n");
            return 1;
        }
        ++length;

        if (c >= 'a' && c <= 'z') {
            ++counts[c - 'a'];
        }
    }

    if (!saw_newline && length == 0 && ferror(stdin)) {
        fprintf(stderr, "error: failed to read input\n");
        return 1;
    }

    int first = 1;
    for (int i = 0; i < 26; ++i) {
        if (counts[i] != 0) {
            if (!first) {
                if (putchar(' ') == EOF) {
                    fprintf(stderr, "error: failed to write output\n");
                    return 1;
                }
            }
            first = 0;
            if (printf("%c:%d", 'a' + i, counts[i]) < 0) {
                fprintf(stderr, "error: failed to write output\n");
                return 1;
            }
        }
    }

    if (putchar('\n') == EOF) {
        fprintf(stderr, "error: failed to write output\n");
        return 1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_LINE_BYTES (1024 * 1024)

static int read_one_line(char **out_buf, size_t *out_len, int *out_has_line)
{
    char *buf = NULL;
    size_t len = 0;
    size_t cap = 0;
    int c;
    int has_line = 0;

    while ((c = fgetc(stdin)) != EOF) {
        if (c == '\n') {
            has_line = 1;
            break;
        }

        if (len >= MAX_LINE_BYTES) {
            while ((c = fgetc(stdin)) != EOF && c != '\n') {
            }
            if (c == '\n') {
                has_line = 1;
            }
            free(buf);
            return -2;
        }

        if (len == cap) {
            size_t newcap = cap ? cap * 2 : 256;
            if (newcap > MAX_LINE_BYTES + 1) {
                newcap = MAX_LINE_BYTES + 1;
            }
            if (newcap <= cap) {
                free(buf);
                return -1;
            }
            char *tmp = realloc(buf, newcap);
            if (tmp == NULL) {
                free(buf);
                return -1;
            }
            buf = tmp;
            cap = newcap;
        }

        buf[len++] = (char)c;
    }

    if (ferror(stdin)) {
        free(buf);
        return -1;
    }

    if (len == 0 && !has_line) {
        free(buf);
        *out_buf = NULL;
        *out_len = 0;
        *out_has_line = 0;
        return 0;
    }

    if (len > 0) {
        char *tmp = realloc(buf, len + 1);
        if (tmp == NULL) {
            free(buf);
            return -1;
        }
        buf = tmp;
        buf[len] = '\0';
    }

    *out_buf = buf;
    *out_len = len;
    *out_has_line = 1;
    return 0;
}

int main(void)
{
    char *line = NULL;
    size_t len = 0;
    int has_line = 0;

    int rc = read_one_line(&line, &len, &has_line);
    if (rc == -2) {
        fprintf(stderr, "error: input line exceeds %d bytes\n", MAX_LINE_BYTES);
        return EXIT_FAILURE;
    }
    if (rc != 0) {
        fprintf(stderr, "error: failed to read input\n");
        free(line);
        return EXIT_FAILURE;
    }

    if (!has_line) {
        free(line);
        return EXIT_SUCCESS;
    }

    size_t counts[256] = {0};
    for (size_t i = 0; i < len; i++) {
        counts[(unsigned char)line[i]]++;
    }

    for (int value = 0; value < 256; value++) {
        for (size_t i = 0; i < counts[value]; i++) {
            if (putchar(value) == EOF) {
                fprintf(stderr, "error: failed to write output\n");
                free(line);
                return EXIT_FAILURE;
            }
        }
    }

    if (putchar('\n') == EOF) {
        fprintf(stderr, "error: failed to write output\n");
        free(line);
        return EXIT_FAILURE;
    }

    free(line);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_HEX_LEN 100000
#define DEC_BASE 1000000000U

static int hex_value(char c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int mul_add(uint32_t *limbs, size_t *n, size_t cap,
                   uint64_t mult, uint64_t add)
{
    uint64_t carry = add;
    for (size_t i = 0; i < *n; ++i) {
        uint64_t t = (uint64_t)limbs[i] * mult + carry;
        limbs[i] = (uint32_t)(t % DEC_BASE);
        carry = t / DEC_BASE;
    }
    while (carry > 0) {
        if (*n >= cap) return 0;
        limbs[*n] = (uint32_t)(carry % DEC_BASE);
        carry /= DEC_BASE;
        ++(*n);
    }
    return 1;
}

static uint64_t parse_chunk(const char *s, size_t len)
{
    uint64_t value = 0;
    for (size_t i = 0; i < len; ++i) {
        value = value * 16U + (uint64_t)hex_value(s[i]);
    }
    return value;
}

int main(void)
{
    char buf[MAX_HEX_LEN + 2];

    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        fputs("error: no input\n", stderr);
        return EXIT_FAILURE;
    }

    char *nl = strchr(buf, '\n');
    if (nl != NULL) {
        *nl = '\0';
        if (nl > buf && nl[-1] == '\r') {
            nl[-1] = '\0';
        }
    } else if (strlen(buf) == sizeof(buf) - 1) {
        fputs("error: input too long\n", stderr);
        return EXIT_FAILURE;
    }

    size_t len = strlen(buf);
    if (len == 0 || len > MAX_HEX_LEN) {
        fputs("error: invalid input length\n", stderr);
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < len; ++i) {
        if (hex_value(buf[i]) < 0) {
            fputs("error: invalid hexadecimal digit\n", stderr);
            return EXIT_FAILURE;
        }
    }

    size_t cap = len / 4 + 16;
    uint32_t *limbs = calloc(cap, sizeof(*limbs));
    if (limbs == NULL) {
        fputs("error: out of memory\n", stderr);
        return EXIT_FAILURE;
    }

    size_t n = 1;
    limbs[0] = 0;

    size_t pos = 0;
    size_t first = len % 8;
    if (first != 0) {
        uint64_t value = parse_chunk(buf, first);
        uint64_t mult = 1ULL << (4 * first);
        if (!mul_add(limbs, &n, cap, mult, value)) {
            fputs("error: conversion failed\n", stderr);
            free(limbs);
            return EXIT_FAILURE;
        }
        pos += first;
    }

    while (pos < len) {
        uint64_t value = parse_chunk(buf + pos, 8);
        if (!mul_add(limbs, &n, cap, 1ULL << 32, value)) {
            fputs("error: conversion failed\n", stderr);
            free(limbs);
            return EXIT_FAILURE;
        }
        pos += 8;
    }

    printf("%u", (unsigned)limbs[n - 1]);
    for (size_t i = n - 1; i > 0; --i) {
        printf("%09u", (unsigned)limbs[i - 1]);
    }
    putchar('\n');

    free(limbs);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

#define MAX_INPUT 128

int main(void)
{
    char buf[MAX_INPUT + 1];
    size_t len = 0;
    int ch;

    while ((ch = getchar()) != EOF) {
        if (len == MAX_INPUT) {
            fprintf(stderr, "input too large\n");
            return 1;
        }
        buf[len++] = (char)ch;
    }

    if (ferror(stdin)) {
        fprintf(stderr, "read error\n");
        return 1;
    }

    if (len == 0) {
        fprintf(stderr, "no input\n");
        return 1;
    }

    if (memchr(buf, '\0', len) != NULL) {
        fprintf(stderr, "invalid input\n");
        return 1;
    }

    buf[len] = '\0';

    size_t i = 0;
    while (i < len && isspace((unsigned char)buf[i])) {
        i++;
    }

    int negative = 0;
    if (i < len && (buf[i] == '-' || buf[i] == '+')) {
        negative = (buf[i] == '-');
        i++;
    }

    if (i >= len || !isdigit((unsigned char)buf[i])) {
        fprintf(stderr, "invalid integer\n");
        return 1;
    }

    unsigned long long magnitude = 0;
    while (i < len && isdigit((unsigned char)buf[i])) {
        int digit = buf[i] - '0';

        if (magnitude > (ULLONG_MAX - (unsigned long long)digit) / 10ULL) {
            fprintf(stderr, "integer out of range\n");
            return 1;
        }

        magnitude = magnitude * 10ULL + (unsigned long long)digit;
        i++;
    }

    while (i < len && isspace((unsigned char)buf[i])) {
        i++;
    }

    if (i != len) {
        fprintf(stderr, "trailing data\n");
        return 1;
    }

    unsigned long long limit = negative
        ? (unsigned long long)INT_MAX + 1ULL
        : (unsigned long long)INT_MAX;

    if (magnitude > limit) {
        fprintf(stderr, "integer out of range\n");
        return 1;
    }

    unsigned int result;
    if (negative) {
        result = (unsigned int)(0ULL - magnitude);
    } else {
        result = (unsigned int)magnitude;
    }

    printf("%x\n", result);
    return 0;
}

