#include <stdio.h>
#include <stdint.h>

int main(void) {
    int has_digit = 0;
    int state = 0; /* 0: digits, 1: after CR, 2: after LF */
    int ok = 1;
    size_t digit_count = 0;

    for (;;) {
        int c = fgetc(stdin);
        if (c == EOF) {
            break;
        }

        if (!ok) {
            continue;
        }

        if (state == 0) {
            if (c >= '0' && c <= '9') {
                has_digit = 1;
                if (digit_count == SIZE_MAX) {
                    ok = 0;
                } else {
                    ++digit_count;
                }
            } else if (c == '\r') {
                if (!has_digit) {
                    ok = 0;
                } else {
                    state = 1;
                }
            } else if (c == '\n') {
                if (!has_digit) {
                    ok = 0;
                } else {
                    state = 2;
                }
            } else {
                ok = 0;
            }
        } else if (state == 1) {
            if (c == '\n') {
                state = 2;
            } else {
                ok = 0;
            }
        } else {
            ok = 0;
        }
    }

    if (ferror(stdin)) {
        ok = 0;
    }
    if (!has_digit) {
        ok = 0;
    }
    if (state == 1) {
        ok = 0;
    }

    puts(ok ? "1" : "0");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100000

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "error: could not read n\n");
        return 1;
    }

    if (n < 0 || n > MAX_N) {
        fprintf(stderr, "error: n must be between 0 and %d\n", MAX_N);
        return 1;
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            fprintf(stderr, "error: out of memory\n");
            return 1;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            fprintf(stderr, "error: could not read integer %d\n", i);
            free(a);
            return 1;
        }
    }

    for (int i = 0; i < n - 1; ++i) {
        int swapped = 0;
        for (int j = 0; j < n - 1 - i; ++j) {
            if (a[j] > a[j + 1]) {
                int tmp = a[j];
                a[j] = a[j + 1];
                a[j + 1] = tmp;
                swapped = 1;
            }
        }
        if (!swapped) {
            break;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", a[i]);
    }
    if (n > 0) {
        putchar('\n');
    }

    free(a);
    return 0;
}

