#define MAX_N 100000

static void selection_sort(int *a, size_t n)
{
    for (size_t i = 0; i + 1 < n; ++i) {
        size_t min = i;
        for (size_t j = i + 1; j < n; ++j) {
            if (a[j] < a[min]) {
                min = j;
            }
        }
        if (min != i) {
            int tmp = a[i];
            a[i] = a[min];
            a[min] = tmp;
        }
    }
}

int main(void)
{
    long n_input;

    if (scanf("%ld", &n_input) != 1) {
        fprintf(stderr, "error: failed to read n\n");
