    int *a = NULL;
    if (n > 0) {
        a = malloc(n * sizeof *a);
        if (a == NULL) {
            fprintf(stderr, "error: out of memory\n");
            return 1;
        }
    }

    for (size_t i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            fprintf(stderr, "error: failed to read integer %zu\n", i + 1);
            free(a);
            return 1;
        }
    }

    selection_sort(a, n);

    for (size_t i = 0; i < n; ++i) {
        if (i != 0) {
