    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 1000000

static void swap_int(int *a, int *b)
{
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

static void quicksort(int *a, int lo, int hi)
{
    if (lo < hi) {
        int pivot = a[lo + (hi - lo) / 2];
        int i = lo - 1;
        int j = hi + 1;

        for (;;) {
            do {
                ++i;
            } while (a[i] < pivot);
            do {
                --j;
            } while (a[j] > pivot);
            if (i >= j) {
                break;
            }
            swap_int(&a[i], &a[j]);
        }

        quicksort(a, lo, j);
        quicksort(a, j + 1, hi);
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "error: failed to read n\n");
        return 1;
    }
    if (n < 0) {
        fprintf(stderr, "error: n must be non-negative\n");
        return 1;
    }
    if (n > MAX_N) {
        fprintf(stderr, "error: n too large\n");
        return 1;
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            fprintf(stderr, "error: out of memory\n");
            return 1;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            fprintf(stderr, "error: failed to read element %d\n", i);
            free(a);
            return 1;
        }
    }

    if (n > 0) {
        quicksort(a, 0, n - 1);
    }

    for (int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i + 1 < n) {
            putchar(' ');
        }
    }
    if (n > 0) {
        putchar('\n');
    }

    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static void merge(int *a, int *tmp, size_t lo, size_t mid, size_t hi)
{
    size_t i = lo;
    size_t j = mid;
    size_t k = lo;

    while (i < mid && j < hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }

    while (i < mid) {
        tmp[k++] = a[i++];
    }

    while (j < hi) {
        tmp[k++] = a[j++];
    }

    for (k = lo; k < hi; ++k) {
        a[k] = tmp[k];
    }
}

static void merge_sort_range(int *a, int *tmp, size_t lo, size_t hi)
{
    if (hi - lo <= 1) {
        return;
    }

    size_t mid = lo + (hi - lo) / 2;
    merge_sort_range(a, tmp, lo, mid);
    merge_sort_range(a, tmp, mid, hi);
    merge(a, tmp, lo, mid, hi);
}

int main(void)
{
    long long n_input;

    if (scanf("%lld", &n_input) != 1) {
        fprintf(stderr, "error: invalid or missing count\n");
        return 1;
    }

    if (n_input < 0) {
        fprintf(stderr, "error: count must be non-negative\n");
        return 1;
    }

    size_t n = (size_t)n_input;

    if (n > (size_t)-1 / sizeof(int)) {
        fprintf(stderr, "error: count too large\n");
        return 1;
    }

    int *values = NULL;
    int *helper = NULL;

    if (n > 0) {
        values = malloc(n * sizeof(int));
        helper = malloc(n * sizeof(int));

        if (values == NULL || helper == NULL) {
            fprintf(stderr, "error: out of memory\n");
            free(values);
            free(helper);
            return 1;
        }

        for (size_t i = 0; i < n; ++i) {
            if (scanf("%d", &values[i]) != 1) {
                fprintf(stderr, "error: invalid integer at position %zu\n", i);
                free(values);
                free(helper);
                return 1;
            }
        }

        merge_sort_range(values, helper, 0, n);
    }

    for (size_t i = 0; i < n; ++i) {
        printf("%d", values[i]);
        if (i + 1 < n) {
            putchar(' ');
        }
    }
    putchar('\n');

    free(values);
    free(helper);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_N 1000000

static void sift_down(long long *arr, size_t n, size_t i)
{
    while (1) {
        size_t left = 2 * i + 1;
        if (left >= n) {
            break;
        }

        size_t right = left + 1;
        size_t max_index = i;

        if (arr[left] > arr[max_index]) {
            max_index = left;
        }
        if (right < n && arr[right] > arr[max_index]) {
            max_index = right;
        }
        if (max_index == i) {
            break;
        }

        long long tmp = arr[i];
        arr[i] = arr[max_index];
        arr[max_index] = tmp;

        i = max_index;
    }
}

static void heap_sort(long long *arr, size_t n)
{
    if (arr == NULL || n < 2) {
        return;
    }

    for (size_t i = n / 2; i > 0; --i) {
        sift_down(arr, n, i - 1);
    }

    for (size_t i = n; i > 1; --i) {
        long long tmp = arr[0];
        arr[0] = arr[i - 1];
        arr[i - 1] = tmp;

        sift_down(arr, i - 1, 0);
    }
}

int main(void)
{
    long long count_ll;

    if (scanf("%lld", &count_ll) != 1) {
        fprintf(stderr, "error: missing or invalid count\n");
        return 1;
    }
    if (count_ll < 0 || count_ll > MAX_N) {
        fprintf(stderr, "error: count out of range\n");
        return 1;
    }

    size_t count = (size_t)count_ll;
    long long *arr = NULL;

    if (count > 0) {
        arr = malloc(count * sizeof *arr);
        if (arr == NULL) {
            fprintf(stderr, "error: out of memory\n");
            return 1;
        }
    }

    for (size_t i = 0; i < count; ++i) {
        if (scanf("%lld", &arr[i]) != 1) {
            fprintf(stderr, "error: invalid or missing integer at index %zu\n", i);
            free(arr);
            return 1;
        }
    }

    heap_sort(arr, count);

    for (size_t i = 0; i < count; ++i) {
        printf("%lld\n", arr[i]);
    }

    free(arr);
    return 0;
}

#include <stdio.h>
