    if (scanf("%d", &n) != 1) {
        printf("-1\n");
        return 0;
    }

    if (n < 0 || n > MAX_N) {
        printf("-1\n");
        return 0;
    }

    int *a = NULL;
    if (n > 0) {
        a = malloc((size_t)n * sizeof *a);
        if (a == NULL) {
            printf("-1\n");
            return 0;
        }
        for (int i = 0; i < n; ++i) {
            if (scanf("%d", &a[i]) != 1) {
                free(a);
                printf("-1\n");
                return 0;
            }
        }
    }

    int x;
    if (scanf("%d", &x) != 1) {
        free(a);
        printf("-1\n");
        return 0;
    }

    int lo = 0, hi = n - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == x) {
            ans = mid;
            break;
        } else if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    printf("%d\n", ans);
    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    long long n;

    if (scanf("%lld", &n) != 1) {
        fprintf(stderr, "error: invalid count\n");
        return EXIT_FAILURE;
    }
    if (n < 2) {
        fprintf(stderr, "error: at least two integers are required\n");
        return EXIT_FAILURE;
    }

    long long max1 = 0, max2 = 0;
    int have_first = 0, have_second = 0;

    for (long long i = 0; i < n; ++i) {
        long long x;

        if (scanf("%lld", &x) != 1) {
            fprintf(stderr, "error: invalid integer at position %lld\n", i + 1);
            return EXIT_FAILURE;
        }

        if (!have_first) {
            max1 = x;
            have_first = 1;
        } else if (!have_second) {
            if (x >= max1) {
                max2 = max1;
                max1 = x;
            } else {
                max2 = x;
            }
            have_second = 1;
        } else if (x > max1) {
            max2 = max1;
            max1 = x;
        } else if (x > max2) {
            max2 = x;
        }
    }

    if (!have_first || !have_second) {
        fprintf(stderr, "error: insufficient input\n");
        return EXIT_FAILURE;
    }

    printf("%lld %lld\n", max1, max2);
    return EXIT_SUCCESS;
}

