static int read_matrix(double m[3][3]) {
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (scanf("%lf", &m[i][j]) != 1) {
                return 0;
            }
        }
    }
    return 1;
}

int main(void) {
    double a[3][3];
    double b[3][3];
    double product[3][3];

    if (!read_matrix(a) || !read_matrix(b)) {
        fprintf(stderr, "error: expected two 3x3 matrices (18 numeric values)\n");
        return EXIT_FAILURE;
    }

    char extra[2];
    if (scanf(" %1s", extra) == 1) {
        fprintf(stderr, "error: unexpected extra input\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            product[i][j] = 0.0;
            for (int k = 0; k < 3; ++k) {
                product[i][j] += a[i][k] * b[k][j];
            }
        }
    }

