#include <stdio.h>
#include <string.h>

#define N 10

static int in_bounds(int r, int c)
{
    return r >= 0 && r < N && c >= 0 && c < N;
}

int main(void)
{
    char grid[N][N];
    char line[256];
    int rows = 0;

    while (rows < N && fgets(line, sizeof line, stdin)) {
        size_t len = strcspn(line, "\r\n");
        line[len] = '\0';

        if (len == 0) {
            continue; /* skip blank lines */
        }
        if (len != N) {
            fprintf(stderr, "invalid row length: expected %d, got %zu\n", N, len);
            return 1;
        }

        for (int c = 0; c < N; c++) {
            if (line[c] != '.' && line[c] != '#') {
                fprintf(stderr, "invalid character: %c\n", line[c]);
                return 1;
            }
            grid[rows][c] = line[c];
        }
        rows++;
    }

    if (rows != N) {
        fprintf(stderr, "invalid grid height: expected %d, got %d\n", N, rows);
        return 1;
    }

    int visited[N][N] = {0};
    int count = 0;
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < N; r++) {
        for (int c = 0; c < N; c++) {
            if (grid[r][c] != '#' || visited[r][c]) {
                continue;
            }

            count++;
            int q[N * N][2];
            int head = 0, tail = 0;
            q[tail][0] = r;
            q[tail][1] = c;
            tail++;
            visited[r][c] = 1;

            while (head < tail) {
                int cr = q[head][0];
                int cc = q[head][1];
                head++;

                for (int d = 0; d < 4; d++) {
                    int nr = cr + dr[d];
                    int nc = cc + dc[d];
                    if (in_bounds(nr, nc) && grid[nr][nc] == '#' && !visited[nr][nc]) {
                        visited[nr][nc] = 1;
                        q[tail][0] = nr;
                        q[tail][1] = nc;
                        tail++;
                    }
                }
            }
        }
    }

    printf("%d\n", count);
    return 0;
}

