#include <stdio.h>
#include <stdlib.h>

#define MAX_ITEMS 10000000LL

static int compare_ll(const void *a, const void *b)
{
    const long long *x = a;
    const long long *y = b;
    return (*x > *y) - (*x < *y);
}

int main(void)
{
    long long n, capacity;

    if (scanf("%lld %lld", &n, &capacity) != 2) {
        fprintf(stderr, "error: expected n and capacity\n");
        return 1;
    }

    if (n < 0 || n > MAX_ITEMS) {
        fprintf(stderr, "error: invalid item count\n");
        return 1;
    }

    if (capacity < 0) {
        capacity = 0;
    }

    long long *weights = NULL;
    if (n > 0) {
        weights = malloc((size_t)n * sizeof(*weights));
        if (weights == NULL) {
            fprintf(stderr, "error: out of memory\n");
            return 1;
        }
    }

    for (long long i = 0; i < n; i++) {
        if (scanf("%lld", &weights[i]) != 1) {
            fprintf(stderr, "error: invalid weight\n");
            free(weights);
            return 1;
        }
        if (weights[i] < 0) {
            fprintf(stderr, "error: negative weight\n");
            free(weights);
            return 1;
        }
    }

    qsort(weights, (size_t)n, sizeof(*weights), compare_ll);

    long long used = 0;
    size_t count = 0;

    for (long long i = 0; i < n; i++) {
        if (weights[i] <= capacity - used) {
            used += weights[i];
            count++;
        } else {
            break;
        }
    }

    printf("%zu\n", count);

    free(weights);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>

#define MAX_COUNT ((size_t)10000000)

int main(void)
{
    size_t n;

    if (scanf("%zu", &n) != 1) {
        fprintf(stderr, "error: could not read n\n");
        return 1;
    }

    if (n > MAX_COUNT) {
        fprintf(stderr, "error: n is too large\n");
        return 1;
    }

    int *arr = NULL;
    size_t cap = 0;
    size_t count = 0;

    for (size_t i = 0; i < n; ++i) {
        if (count == cap) {
            size_t new_cap;

            if (cap == 0) {
                new_cap = 16;
            } else {
                if (cap > SIZE_MAX / 2) {
                    fprintf(stderr, "error: capacity overflow\n");
                    free(arr);
                    return 1;
                }
                new_cap = cap * 2;
            }

            if (new_cap > SIZE_MAX / sizeof *arr) {
                fprintf(stderr, "error: allocation size overflow\n");
                free(arr);
                return 1;
            }

            int *tmp = realloc(arr, new_cap * sizeof *arr);
            if (tmp == NULL) {
                fprintf(stderr, "error: out of memory\n");
                free(arr);
                return 1;
            }

            arr = tmp;
            cap = new_cap;
        }

        int value;
        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "error: could not read integer %zu\n", i);
            free(arr);
            return 1;
        }

        arr[count++] = value;
    }

    long long sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += arr[i];
    }

    printf("%lld\n", sum);

    free(arr);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

struct Point {
    int x;
    int y;
};

static void print_unsigned128(int carry, unsigned long long low)
{
    if (carry == 0 && low == 0) {
        putchar('0');
        putchar('\n');
        return;
    }

    unsigned long long hi = carry ? 1ULL : 0ULL;
    char digits[64];
    int count = 0;

    while (hi != 0ULL || low != 0ULL) {
        unsigned long long remainder = 0ULL;
        unsigned long long qhi = 0ULL;
        unsigned long long qlo = 0ULL;

        for (int i = 63; i >= 0; --i) {
            remainder = (remainder << 1) | ((hi >> i) & 1ULL);
            if (remainder >= 10ULL) {
                remainder -= 10ULL;
                qhi |= (1ULL << i);
            }
        }

        for (int i = 63; i >= 0; --i) {
            remainder = (remainder << 1) | ((low >> i) & 1ULL);
            if (remainder >= 10ULL) {
                remainder -= 10ULL;
                qlo |= (1ULL << i);
            }
        }

        digits[count++] = (char)('0' + remainder);
        hi = qhi;
        low = qlo;
    }

    for (int i = count - 1; i >= 0; --i) {
        putchar(digits[i]);
    }
    putchar('\n');
}

int main(void)
{
    char input[4096];
    size_t length = 0;

    while (length < sizeof(input) - 1) {
        size_t got = fread(input + length, 1, sizeof(input) - length - 1, stdin);
        if (got == 0) {
            break;
        }
        length += got;
    }

    if (ferror(stdin)) {
        fprintf(stderr, "error reading stdin\n");
        return 1;
    }

    if (length == sizeof(input) - 1) {
        char extra;
        if (fread(&extra, 1, 1, stdin) == 1) {
            fprintf(stderr, "input too large\n");
            return 1;
        }
        if (ferror(stdin)) {
            fprintf(stderr, "error reading stdin\n");
            return 1;
        }
    }

    input[length] = '\0';

    int x1, y1, x2, y2;
    int consumed = 0;
    int parsed = sscanf(input, "%d %d %d %d %n", &x1, &y1, &x2, &y2, &consumed);

    if (parsed != 4) {
        fprintf(stderr, "expected four integers\n");
        return 1;
    }

    const char *p = input + consumed;
    while (isspace((unsigned char)*p)) {
        ++p;
    }
    if (*p != '\0') {
        fprintf(stderr, "unexpected trailing input\n");
        return 1;
    }

    struct Point p1 = { x1, y1 };
    struct Point p2 = { x2, y2 };

    long long dx = (long long)p1.x - (long long)p2.x;
    long long dy = (long long)p1.y - (long long)p2.y;

    unsigned long long ax = dx < 0 ? (unsigned long long)(-dx) : (unsigned long long)dx;
    unsigned long long ay = dy < 0 ? (unsigned long long)(-dy) : (unsigned long long)dy;

    unsigned long long sqx = ax * ax;
    unsigned long long sqy = ay * ay;

    int carry = (sqx > (unsigned long long)-1 - sqy) ? 1 : 0;
    unsigned long long low = sqx + sqy;

    print_unsigned128(carry, low);
    return 0;
}

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>

#define INPUT_CAPACITY 4096

typedef struct {
    double re;
    double im;
} Complex;

int main(void) {
    char input[INPUT_CAPACITY + 1];
    size_t nread = fread(input, 1, INPUT_CAPACITY, stdin);

    if (ferror(stdin)) {
        fprintf(stderr, "error: failed to read standard input\n");
        return EXIT_FAILURE;
    }

    if (nread == INPUT_CAPACITY) {
        int extra = fgetc(stdin);
        if (extra != EOF) {
            fprintf(stderr, "error: input is too large\n");
            return EXIT_FAILURE;
        }
    }

    input[nread] = '\0';

    Complex a = {0.0, 0.0};
    Complex b = {0.0, 0.0};
    int consumed = 0;
    int parsed = sscanf(input, "%lf %lf %lf %lf %n",
                        &a.re, &a.im, &b.re, &b.im, &consumed);

    if (parsed != 4) {
        fprintf(stderr, "error: expected four numeric values\n");
        return EXIT_FAILURE;
    }

    while (consumed < (int)nread &&
           isspace((unsigned char)input[consumed])) {
        ++consumed;
    }

    if (consumed != (int)nread) {
        fprintf(stderr, "error: unexpected trailing input\n");
        return EXIT_FAILURE;
    }

    Complex product;
    product.re = a.re * b.re - a.im * b.im;
    product.im = a.re * b.im + a.im * b.re;

    printf("%.6f %.6f\n", product.re, product.im);
    return EXIT_SUCCESS;
}

#include <stdio.h>
