} Node;

#define MAX_NODES 1000000

static void free_list(Node *head) {
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void) {
    long long n;

    if (scanf("%lld", &n) != 1) {
        fprintf(stderr, "error: missing or invalid count\n");
        return 1;
    }
    if (n < 0 || n > MAX_NODES) {
        fprintf(stderr, "error: invalid input size\n");
        return 1;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (long long i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "error: missing or invalid integer\n");
            free_list(head);
            return 1;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            fprintf(stderr, "error: out of memory\n");
            free_list(head);
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (tail == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }

    size_t count = (size_t)n;
    int *stack = NULL;
    if (count > 0) {
        stack = malloc(count * sizeof *stack);
        if (stack == NULL) {
            fprintf(stderr, "error: out of memory\n");
            free_list(head);
            return 1;
        }
    }

    size_t sp = 0;
    for (Node *cur = head; cur != NULL; cur = cur->next) {
        if (sp >= count) {
            fprintf(stderr, "error: list size mismatch\n");
            free(stack);
            free_list(head);
            return 1;
        }
        stack[sp++] = cur->value;
    }

    int first = 1;
    for (size_t i = sp; i > 0; --i) {
        if (!first) {
            putchar(' ');
        }
        printf("%d", stack[i - 1]);
        first = 0;
    }
    putchar('\n');

    free(stack);
    free_list(head);
    return 0;
}

#include <stdio.h>
