typedef struct Node {
    int value;
    struct Node *next;
} Node;

static void free_list(Node *head)
{
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "error: could not read list size\n");
        return 1;
    }

    if (n < 0) {
        fprintf(stderr, "error: list size must be non-negative\n");
        return 1;
    }

    Node *head = NULL;
    Node *tail = NULL;

    for (int i = 0; i < n; ++i) {
        int value;
        if (scanf("%d", &value) != 1) {
            fprintf(stderr, "error: could not read element %d\n", i);
            free_list(head);
            return 1;
        }

        Node *node = malloc(sizeof *node);
        if (node == NULL) {
            fprintf(stderr, "error: out of memory\n");
            free_list(head);
            return 1;
        }

        node->value = value;
        node->next = NULL;

        if (tail == NULL) {
            head = node;
        } else {
            tail->next = node;
        }
        tail = node;
    }

    /* Reverse the list in place by relinking pointers. */
    Node *previous = NULL;
    Node *current = head;
    while (current != NULL) {
        Node *next = current->next;
        current->next = previous;
        previous = current;
        current = next;
    }
    head = previous;

    current = head;
    while (current != NULL) {
        printf("%d", current->value);
        if (current->next != NULL) {
            putchar(' ');
        }
        current = current->next;
    }
    putchar('\n');

    free_list(head);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAX_NODES 1000000

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

int main(void) {
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "error: failed to read n\n");
        return 1;
    }
    if (n < 0 || n > MAX_NODES) {
        fprintf(stderr, "error: n must be between 0 and %d\n", MAX_NODES);
        return 1;
    }

    Node *pool = NULL;
    if (n > 0) {
        pool = calloc((size_t)n, sizeof *pool);
        if (pool == NULL) {
            perror("calloc");
            return 1;
        }
    }

    Node *root = NULL;
    size_t used = 0;

    for (int i = 0; i < n; ++i) {
        int x;
        if (scanf("%d", &x) != 1) {
            fprintf(stderr, "error: failed to read integer %d\n", i);
            free(pool);
            return 1;
        }

        Node *node = &pool[used++];
        node->value = x;
        node->left = NULL;
        node->right = NULL;

        if (root == NULL) {
            root = node;
        } else {
            Node *cur = root;
            Node *parent = NULL;
            while (cur != NULL) {
                parent = cur;
                if (x <= cur->value) {
                    cur = cur->left;
                } else {
                    cur = cur->right;
                }
            }
            if (x <= parent->value) {
                parent->left = node;
            } else {
                parent->right = node;
            }
        }
    }

    Node **stack = NULL;
    if (n > 0) {
        stack = malloc((size_t)n * sizeof *stack);
        if (stack == NULL) {
            perror("malloc");
            free(pool);
            return 1;
        }
    }

    size_t sp = 0;
    Node *cur = root;

    while (cur != NULL || sp > 0) {
        while (cur != NULL) {
            if (sp >= (size_t)n) {
                fprintf(stderr, "error: traversal stack overflow\n");
                free(stack);
                free(pool);
                return 1;
            }
            stack[sp++] = cur;
            cur = cur->left;
        }

        cur = stack[--sp];
        printf("%d\n", cur->value);
        cur = cur->right;
    }

    free(stack);
    free(pool);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
