#include <limits.h>

#define STACK_CAPACITY 100
#define LINE_CAPACITY 256

static int stack[STACK_CAPACITY];
static size_t stack_size = 0;

static int push_value(int value)
{
    if (stack_size == STACK_CAPACITY) {
        return -1;
    }
    stack[stack_size++] = value;
    return 0;
}

static int pop_value(int *value)
{
    if (stack_size == 0) {
        return -1;
    }
    *value = stack[--stack_size];
    return 0;
}

static void drain_line(void)
{
    int c;
    while ((c = getchar()) != '\n' && c != EOF) {
    }
}

int main(void)
{
    char line[LINE_CAPACITY];

    while (fgets(line, sizeof line, stdin) != NULL) {
        size_t len = strlen(line);

        if (len == sizeof(line) - 1 && line[len - 1] != '\n') {
            drain_line();
            fprintf(stderr, "input line too long\n");
            continue;
        }

        char *cursor = line;
        while (isspace((unsigned char)*cursor)) {
            cursor++;
        }

        if (*cursor == '\0') {
            continue;
        }

        if (*cursor == 'q') {
            char *rest = cursor + 1;
            while (isspace((unsigned char)*rest)) {
                rest++;
            }
            if (*rest != '\0') {
                fprintf(stderr, "invalid command\n");
                continue;
            }
            break;
        }

        if (*cursor == 'o') {
            char *rest = cursor + 1;
            while (isspace((unsigned char)*rest)) {
                rest++;
            }
            if (*rest != '\0') {
                fprintf(stderr, "invalid command\n");
                continue;
            }

            int value;
            if (pop_value(&value) != 0) {
                fprintf(stderr, "stack empty\n");
            } else {
                printf("%d\n", value);
            }
            continue;
        }

        if (*cursor == 'p') {
            char *rest = cursor + 1;
            while (isspace((unsigned char)*rest)) {
                rest++;
            }
            if (*rest == '\0') {
                fprintf(stderr, "missing number\n");
                continue;
            }

            errno = 0;
            char *end = NULL;
            long value = strtol(rest, &end, 10);

            while (isspace((unsigned char)*end)) {
                end++;
            }
            if (*end != '\0') {
                fprintf(stderr, "invalid number\n");
                continue;
            }
            if (errno == ERANGE || value < INT_MIN || value > INT_MAX) {
                fprintf(stderr, "number out of range\n");
                continue;
            }
            if (push_value((int)value) != 0) {
                fprintf(stderr, "stack full\n");
                continue;
            }
            continue;
        }

        fprintf(stderr, "unknown command\n");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>

#define CAPACITY 100
#define LINE_CAPACITY 256

typedef struct {
    int items[CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
} Queue;

static int enqueue(Queue *queue, int value) {
    if (queue->count == CAPACITY) {
        return -1;
    }
    queue->items[queue->tail] = value;
    queue->tail = (queue->tail + 1) % CAPACITY;
    ++queue->count;
    return 0;
}

static int dequeue(Queue *queue, int *value) {
    if (queue->count == 0) {
        return -1;
    }
    *value = queue->items[queue->head];
    queue->head = (queue->head + 1) % CAPACITY;
    --queue->count;
    return 0;
}

int main(void) {
    Queue queue = {0};
    char line[LINE_CAPACITY];

    for (;;) {
        if (fgets(line, sizeof line, stdin) == NULL) {
            break;
        }

        size_t length = strlen(line);
        if (length == LINE_CAPACITY - 1 && line[length - 1] != '\n') {
            int c;
            do {
                c = fgetc(stdin);
            } while (c != '\n' && c != EOF);
            fprintf(stderr, "error: input line too long\n");
            continue;
        }

        char *cursor = line;
        while (isspace((unsigned char)*cursor)) {
            ++cursor;
        }
        if (*cursor == '\0') {
            continue;
        }

        char *token_end = cursor + strcspn(cursor, " \t\r\n");
        size_t token_length = (size_t)(token_end - cursor);
        char command[16];

        if (token_length >= sizeof command) {
            fprintf(stderr, "error: command too long\n");
            continue;
        }

        memcpy(command, cursor, token_length);
        command[token_length] = '\0';
        cursor = token_end;
        while (isspace((unsigned char)*cursor)) {
            ++cursor;
        }

        if (strcmp(command, "q") == 0) {
            if (*cursor != '\0') {
                fprintf(stderr, "error: unexpected input after q\n");
            }
            break;
        } else if (strcmp(command, "d") == 0) {
            if (*cursor != '\0') {
                fprintf(stderr, "error: unexpected input after d\n");
                continue;
            }

            int value;
            if (dequeue(&queue, &value) != 0) {
                fprintf(stderr, "error: queue empty\n");
            } else {
                printf("%d\n", value);
            }
        } else if (strcmp(command, "e") == 0) {
            if (*cursor == '\0') {
                fprintf(stderr, "error: missing number for e\n");
                continue;
            }

            char *endptr = NULL;
            errno = 0;
            long value = strtol(cursor, &endptr, 10);

            if (errno == ERANGE || value < INT_MIN || value > INT_MAX) {
                fprintf(stderr, "error: number out of range\n");
                continue;
            }
            if (endptr == cursor) {
                fprintf(stderr, "error: invalid number for e\n");
                continue;
            }

            while (isspace((unsigned char)*endptr)) {
                ++endptr;
            }
            if (*endptr != '\0') {
                fprintf(stderr, "error: unexpected input after number\n");
                continue;
            }

            if (enqueue(&queue, (int)value) != 0) {
                fprintf(stderr, "error: queue full\n");
            }
        } else {
            fprintf(stderr, "error: unknown command: %s\n", command);
        }
    }

    return 0;
}

