#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 4096
#define MAX_STACK 4096

static int stack[MAX_STACK];
static size_t stack_top = 0;

static void fail(const char *message)
{
    fprintf(stderr, "error: %s\n", message);
    exit(EXIT_FAILURE);
}

static void push_value(int value)
{
    if (stack_top >= MAX_STACK) {
        fail("stack overflow");
    }
    stack[stack_top++] = value;
}

static int pop_value(void)
{
    if (stack_top == 0) {
        fail("stack underflow");
    }
    return stack[--stack_top];
}

static void read_line(char *buffer, size_t size)
{
    if (fgets(buffer, (int)size, stdin) == NULL) {
        if (ferror(stdin)) {
            fail("input read error");
        }
        buffer[0] = '\0';
        return;
    }

    size_t length = strlen(buffer);
    if (length > 0 && buffer[length - 1] == '\n') {
        buffer[length - 1] = '\0';
    } else if (length == size - 1) {
        fail("input line too long");
    }
}

int main(void)
{
    char line[MAX_INPUT + 1];

    read_line(line, sizeof(line));

    for (size_t i = 0; line[i] != '\0'; ++i) {
        unsigned char ch = (unsigned char)line[i];

        if (isspace(ch)) {
            continue;
        }

        if (isdigit(ch)) {
            push_value(ch - '0');
        } else if (ch == '+' || ch == '-' || ch == '*' || ch == '/') {
            int right = pop_value();
            int left = pop_value();
            int result = 0;

            switch (ch) {
                case '+':
                    result = left + right;
                    break;
                case '-':
                    result = left - right;
                    break;
                case '*':
                    result = left * right;
                    break;
                case '/':
                    if (right == 0) {
                        fail("division by zero");
                    }
                    result = left / right;
                    break;
                default:
                    fail("invalid operator");
            }

            push_value(result);
        } else {
            fail("invalid character in expression");
        }
    }

    if (stack_top != 1) {
        fail("invalid RPN expression");
    }

    printf("%d\n", stack[0]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

#define MAX_LINE 4096

static int parse_term(const char *s, size_t *i, long long *value)
{
    while (isspace((unsigned char)s[*i])) {
        (*i)++;
    }

    int neg = 0;
    if (s[*i] == '+' || s[*i] == '-') {
        neg = (s[*i] == '-');
        (*i)++;
    }

    if (!isdigit((unsigned char)s[*i])) {
        return 0;
    }

    size_t first = *i;
    unsigned long long v = 0;
    unsigned long long limit = neg ? 9223372036854775808ULL : 9223372036854775807ULL;

    while (isdigit((unsigned char)s[*i])) {
        int d = s[*i] - '0';
        if (v > (limit - (unsigned long long)d) / 10) {
            return 0;
        }
        v = v * 10 + (unsigned long long)d;
        (*i)++;
        if (*i - first > 20) {
            return 0;
        }
    }

    if (neg) {
        if (v == 9223372036854775808ULL) {
            *value = LLONG_MIN;
        } else {
            *value = -(long long)v;
        }
    } else {
        *value = (long long)v;
    }

    return 1;
}

static int evaluate(const char *s, long long *result)
{
    size_t i = 0;
    long long acc = 0;
    long long term;

    if (!parse_term(s, &i, &term)) {
        return 0;
    }
    acc = term;

    for (;;) {
        while (isspace((unsigned char)s[i])) {
            i++;
        }

        if (s[i] == '\0') {
            break;
        }

        if (s[i] != '+' && s[i] != '-') {
            return 0;
        }

        char op = s[i];
        i++;

        if (!parse_term(s, &i, &term)) {
            return 0;
        }

        if (op == '+') {
            if ((term > 0 && acc > LLONG_MAX - term) ||
                (term < 0 && acc < LLONG_MIN - term)) {
                return 0;
            }
            acc += term;
        } else {
            if ((term > 0 && acc < LLONG_MIN + term) ||
                (term < 0 && acc > LLONG_MAX + term)) {
                return 0;
            }
            acc -= term;
        }
    }

    while (isspace((unsigned char)s[i])) {
        i++;
    }

    if (s[i] != '\0') {
        return 0;
    }

    *result = acc;
    return 1;
}

int main(void)
{
    char line[MAX_LINE];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        fprintf(stderr, "error: no input\n");
        return 1;
    }

    if (strchr(line, '\n') == NULL && !feof(stdin)) {
        fprintf(stderr, "error: input too long\n");
        return 1;
    }

    line[strcspn(line, "\n")] = '\0';
    size_t len = strlen(line);
    if (len > 0 && line[len - 1] == '\r') {
        line[len - 1] = '\0';
    }

    long long result;
    if (!evaluate(line, &result)) {
        fprintf(stderr, "error: invalid expression\n");
        return 1;
    }

    printf("%lld\n", result);

    int c;
    while ((c = getchar()) != EOF) {
        (void)c;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 8192
#define MAX_WORDS 1024

static int compare_words(const void *left, const void *right)
{
    const char *const *a = left;
    const char *const *b = right;
    return strcmp(*a, *b);
}

static int is_lowercase_word(const char *word)
{
    if (word[0] == '\0') {
        return 0;
    }
    for (const char *p = word; *p != '\0'; ++p) {
        if (*p < 'a' || *p > 'z') {
            return 0;
        }
    }
    return 1;
}

int main(void)
{
    char line[MAX_LINE];
    char *words[MAX_WORDS];
    size_t word_count = 0;

    if (fgets(line, sizeof line, stdin) == NULL) {
        if (ferror(stdin)) {
            fprintf(stderr, "error: failed to read input\n");
            return 1;
        }
        return 0;
    }

    size_t length = strlen(line);
    if (length == sizeof line - 1 && line[length - 1] != '\n' && !feof(stdin)) {
        fprintf(stderr, "error: input line is too long\n");
        return 1;
    }

    for (char *token = strtok(line, " \t\r\n");
         token != NULL;
         token = strtok(NULL, " \t\r\n")) {
        if (word_count == MAX_WORDS) {
            fprintf(stderr, "error: too many words\n");
            return 1;
        }
        if (!is_lowercase_word(token)) {
            fprintf(stderr, "error: invalid word: %s\n", token);
            return 1;
        }
        words[word_count++] = token;
    }

    qsort(words, word_count, sizeof words[0], compare_words);

    for (size_t i = 0; i < word_count; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        fputs(words[i], stdout);
    }
    putchar('\n');

    return 0;
}

#include <stdio.h>
#include <ctype.h>

#define MAX_INPUT 4096

static int roman_value(unsigned char c)
{
    switch (c) {
        case 'I': case 'i': return 1;
        case 'V': case 'v': return 5;
        case 'X': case 'x': return 10;
        case 'L': case 'l': return 50;
        case 'C': case 'c': return 100;
        case 'D': case 'd': return 500;
        case 'M': case 'm': return 1000;
        default: return 0;
    }
}

static int read_all(char *buf, size_t cap)
{
    size_t len = 0;

    for (;;) {
        if (len >= cap - 1) {
            char extra;
            if (fread(&extra, 1, 1, stdin) == 1) {
                return -1;
            }
            if (ferror(stdin)) {
                return -2;
            }
            break;
        }

        size_t space = cap - 1 - len;
        size_t n = fread(buf + len, 1, space, stdin);

        if (n == 0) {
            if (ferror(stdin)) {
                return -2;
            }
            break;
        }
        len += n;
    }

    buf[len] = '\0';
    return 0;
}

static int parse_roman(const char *s, long long *result)
{
    long long total = 0;
    size_t i = 0;
    int found = 0;

    while (s[i] != '\0') {
        int v1 = roman_value((unsigned char)s[i]);
        if (v1 == 0) {
            return -1;
        }
        found = 1;

        if (s[i + 1] != '\0') {
            int v2 = roman_value((unsigned char)s[i + 1]);
            if (v2 == 0) {
                return -1;
            }
            if (v1 < v2) {
                total += (long long)v2 - v1;
                i += 2;
                continue;
            }
        }

        total += v1;
        ++i;
    }

    if (!found) {
        return -1;
    }

    *result = total;
    return 0;
}

int main(void)
{
    char input[MAX_INPUT];
    char cleaned[MAX_INPUT];
    long long value;
    size_t j = 0;

    int rc = read_all(input, sizeof(input));
    if (rc == -1) {
        fprintf(stderr, "error: input too large\n");
        return 1;
    }
    if (rc == -2) {
        fprintf(stderr, "error: failed to read input\n");
        return 1;
    }

    for (size_t i = 0; input[i] != '\0'; ++i) {
        if (isspace((unsigned char)input[i])) {
            continue;
        }
        if (roman_value((unsigned char)input[i]) == 0) {
            fprintf(stderr, "error: invalid roman numeral character\n");
            return 1;
        }
        if (j + 1 >= sizeof(cleaned)) {
            fprintf(stderr, "error: input too large\n");
            return 1;
        }
        cleaned[j++] = input[i];
    }
    cleaned[j] = '\0';

    if (j == 0) {
        fprintf(stderr, "error: empty input\n");
        return 1;
    }

    if (parse_roman(cleaned, &value) != 0) {
        fprintf(stderr, "error: invalid roman numeral\n");
        return 1;
    }

    printf("%lld\n", value);
    return 0;
}

