        return 1;
    }

    if (n < 1 || n > MAX_N) {
        fprintf(stderr, "error: n must be between 1 and %d\n", MAX_N);
        return 1;
    }

    size_t count = (size_t)n * (size_t)n;
    if (count > SIZE_MAX / sizeof(int)) {
        fprintf(stderr, "error: matrix size too large\n");
        return 1;
    }

    int *matrix = malloc(count * sizeof *matrix);
    if (matrix == NULL) {
        fprintf(stderr, "error: out of memory\n");
        return 1;
    }

    int top = 0, bottom = n - 1, left = 0, right = n - 1;
    int value = 1;

    while (top <= bottom && left <= right) {
        for (int col = left; col <= right; ++col)
            matrix[top * n + col] = value++;
        ++top;

        for (int row = top; row <= bottom; ++row)
            matrix[row * n + right] = value++;
        --right;

        if (top <= bottom) {
            for (int col = right; col >= left; --col)
                matrix[bottom * n + col] = value++;
            --bottom;
        }

        if (left <= right) {
            for (int row = bottom; row >= top; --row)
                matrix[row * n + left] = value++;
            ++left;
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (j != 0)
                fputc(' ', stdout);
            fprintf(stdout, "%d", matrix[i * n + j]);
        }
        fputc('\n', stdout);
    }

    free(matrix);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 1000
#define MAX_TERM_LEN (16u * 1024u * 1024u)

static size_t decimal_digits(size_t value)
{
    size_t digits = 1;
    while (value >= 10) {
        value /= 10;
        ++digits;
    }
    return digits;
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "error: expected one integer\n");
        return 1;
    }
    if (n < 0 || n > MAX_N) {
        fprintf(stderr, "error: n must be between 0 and %d\n", MAX_N);
        return 1;
    }

    char *cur = malloc(2);
    if (cur == NULL) {
        fprintf(stderr, "error: out of memory\n");
        return 1;
    }
    cur[0] = '1';
    cur[1] = '\0';
    size_t cur_len = 1;

    for (int i = 0; i < n; ++i) {
        if (fputs(cur, stdout) == EOF || putchar('\n') == EOF) {
            fprintf(stderr, "error: output failed\n");
            free(cur);
            return 1;
        }

        if (i == n - 1)
            break;

        size_t needed = 0;
        for (size_t j = 0; j < cur_len; ) {
            size_t k = j + 1;
            while (k < cur_len && cur[k] == cur[j])
                ++k;
            size_t run = k - j;
            needed += decimal_digits(run) + 1;
            j = k;
        }

        if (needed == 0 || needed + 1 > MAX_TERM_LEN) {
            fprintf(stderr, "error: requested term is too large\n");
            free(cur);
            return 1;
        }

        char *next = malloc(needed + 1);
        if (next == NULL) {
            fprintf(stderr, "error: out of memory\n");
            free(cur);
            return 1;
        }

        size_t pos = 0;
        for (size_t j = 0; j < cur_len; ) {
            size_t k = j + 1;
            while (k < cur_len && cur[k] == cur[j])
                ++k;
            size_t run = k - j;

            char buffer[32];
            int written = snprintf(buffer, sizeof(buffer), "%zu", run);
            if (written < 0 || (size_t)written >= sizeof(buffer)) {
                fprintf(stderr, "error: formatting failed\n");
                free(next);
                free(cur);
                return 1;
            }
            memcpy(next + pos, buffer, (size_t)written);
            pos += (size_t)written;
            next[pos++] = cur[j];
            j = k;
        }
        next[needed] = '\0';

        free(cur);
        cur = next;
        cur_len = needed;
    }

    free(cur);
    if (fflush(stdout) == EOF) {
        fprintf(stderr, "error: output failed\n");
        return 1;
    }
    return 0;
}

