static char *read_one_line(size_t *length_out)
{
    size_t capacity = 64;
    size_t length = 0;
    char *buffer = malloc(capacity);

    if (buffer == NULL) {
        return NULL;
    }

    int c;
    while ((c = fgetc(stdin)) != EOF && c != '\n') {
        if (length >= MAX_INPUT) {
            free(buffer);
            return NULL;
        }

        if (length + 1 >= capacity) {
            size_t new_capacity = capacity * 2;
            if (new_capacity > MAX_INPUT + 1) {
                new_capacity = MAX_INPUT + 1;
            }
            if (new_capacity <= capacity) {
                free(buffer);
                return NULL;
            }

            char *new_buffer = realloc(buffer, new_capacity);
            if (new_buffer == NULL) {
                free(buffer);
                return NULL;
            }
            buffer = new_buffer;
            capacity = new_capacity;
        }

        buffer[length++] = (char)c;
    }

    if (ferror(stdin)) {
        free(buffer);
        return NULL;
    }

    if (length > 0 && buffer[length - 1] == '\r') {
        length--;
    }

    buffer[length] = '\0';
    *length_out = length;
    return buffer;
}

