#define MAX_N 200000
#define BASE 1000000000u
#define MAX_LIMBS 4700

typedef struct {
    uint32_t digits[MAX_LIMBS];
    int length;
} BigInt;

static void big_set_zero(BigInt *x) {
    x->digits[0] = 0;
    x->length = 1;
}

static void big_set_one(BigInt *x) {
    x->digits[0] = 1;
    x->length = 1;
}

static void big_add(const BigInt *a, const BigInt *b, BigInt *result) {
    size_t count = (a->length > b->length) ? (size_t)a->length : (size_t)b->length;
    uint64_t carry = 0;

    for (size_t i = 0; i < count; ++i) {
        uint64_t sum = carry;
        if (i < (size_t)a->length) sum += a->digits[i];
        if (i < (size_t)b->length) sum += b->digits[i];
        result->digits[i] = (uint32_t)(sum % BASE);
        carry = sum / BASE;
    }

    if (carry != 0) {
        result->digits[count] = (uint32_t)carry;
        result->length = (int)(count + 1);
    } else {
        result->length = (int)count;
    }

    if (result->length == 0) {
        result->length = 1;
    }
}

int main(void) {
    char buffer[256];

    if (fgets(buffer, sizeof buffer, stdin) == NULL) {
        return 1;
    }

    char *end = NULL;
    errno = 0;
    long long n = strtoll(buffer, &end, 10);

    if (end == buffer || errno != 0 || n < 0 || n > MAX_N) {
        fprintf(stderr, "invalid or unsupported n\n");
        return 1;
    }

    while (isspace((unsigned char)*end)) {
        ++end;
    }

    if (*end != '\0') {
        fprintf(stderr, "invalid input\n");
        return 1;
    }

    BigInt pool[3];
    big_set_zero(&pool[0]);
    big_set_one(&pool[1]);

    int a = 0, b = 1, c = 2;

    for (long long i = 0; i < n; ++i) {
        big_add(&pool[a], &pool[b], &pool[c]);
        int old = a;
        a = b;
        b = c;
        c = old;
    }

    const BigInt *result = &pool[a];

    if (result->length == 1 && result->digits[0] == 0) {
        putchar('0');
    } else {
        printf("%u", (unsigned)result->digits[result->length - 1]);
        for (int i = result->length - 2; i >= 0; --i) {
            printf("%09u", (unsigned)result->digits[i]);
        }
    }

    putchar('\n');
    return 0;
}

#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

static uint64_t addmod(uint64_t a, uint64_t b, uint64_t m)
{
    if (b >= m - a) {
        return b - (m - a);
    }
    return a + b;
}

static uint64_t mulmod(uint64_t a, uint64_t b, uint64_t m)
{
    uint64_t result = 0;
    a %= m;
    while (b != 0) {
        if (b & 1U) {
            result = addmod(result, a, m);
        }
        b >>= 1;
        a = addmod(a, a, m);
    }
    return result;
}

static uint64_t powmod(uint64_t a, uint64_t e, uint64_t m)
{
    uint64_t result = 1 % m;
    a %= m;
    while (e != 0) {
        if (e & 1U) {
            result = mulmod(result, a, m);
        }
        e >>= 1;
        a = mulmod(a, a, m);
    }
    return result;
}

static int is_prime(uint64_t n)
{
    if (n < 2) {
        return 0;
    }

    static const uint64_t small_primes[] = {
        2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL,
        17ULL, 19ULL, 23ULL, 29ULL, 31ULL, 37ULL
    };
    const size_t count = sizeof(small_primes) / sizeof(small_primes[0]);

    for (size_t i = 0; i < count; ++i) {
        if (n == small_primes[i]) {
            return 1;
        }
        if (n % small_primes[i] == 0) {
            return 0;
        }
    }

    uint64_t d = n - 1;
    int s = 0;
    while ((d & 1ULL) == 0ULL) {
        d >>= 1;
        ++s;
    }

    for (size_t i = 0; i < count; ++i) {
        uint64_t a = small_primes[i] % n;
        if (a == 0) {
            continue;
        }

        uint64_t x = powmod(a, d, n);
        if (x == 1 || x == n - 1) {
            continue;
        }

        int composite = 1;
        for (int r = 1; r < s; ++r) {
            x = mulmod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }

        if (composite) {
            return 0;
        }
    }

    return 1;
}

int main(void)
{
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    printf("%d\n", (n >= 2 && is_prime((uint64_t)n)) ? 1 : 0);
    return 0;
}

