static char input[1 << 20];

static int is_zero(const char *s) {
    while (*s == '0') {
        ++s;
    }
    return *s == '\0';
}

static void div2(char *s) {
    int i = 0;
    int r = 0;
    int w = 0;
    int started = 0;

    for (; s[i] != '\0'; ++i) {
        int cur = r * 10 + (s[i] - '0');
        int q = cur / 2;
        r = cur % 2;

        if (!started && q == 0) {
            continue;
        }
        s[w++] = (char)('0' + q);
        started = 1;
    }

    if (!started) {
        s[w++] = '0';
    }
    s[w] = '\0';
}

int main(void) {
    size_t total = 0;

    for (;;) {
        if (total == sizeof(input) - 1) {
            break;
        }
        size_t got = fread(input + total, 1, sizeof(input) - 1 - total, stdin);
        if (got == 0) {
            break;
        }
        total += got;
    }
    input[total] = '\0';

    size_t i = 0;
    while (isspace((unsigned char)input[i])) {
        ++i;
    }
    if (input[i] == '+') {
        ++i;
    }
    if (!isdigit((unsigned char)input[i])) {
        puts("0");
        return 0;
    }

    size_t start = i;
    while (isdigit((unsigned char)input[i])) {
        ++i;
    }
    input[i] = '\0';

    while (input[start] == '0' && input[start + 1] != '\0') {
        ++start;
    }

    char *num = input + start;
    size_t bits = 0;

    while (!is_zero(num)) {
        size_t len = strlen(num);
        bits += (size_t)((num[len - 1] - '0') & 1);
        div2(num);
    }

    printf("%zu\n", bits);
    return 0;
}

#include <stdio.h>

int main(void) {
    int vals[3];

    if (scanf("%d %d %d", &vals[0], &vals[1], &vals[2]) != 3) {
        return 1;
    }

    int a = vals[0];
    int b = vals[1];
    int m = vals[2];

    if (m == 0) {
        return 1;
    }
    if (m < 0) {
        m = -m;
    }

    unsigned long long base = (unsigned long long)((a % m + m) % m);
    unsigned long long result = 1 % (unsigned long long)m;
    unsigned long long modulus = (unsigned long long)m;

    int exponent = b;
    if (exponent < 0) {
        return 1;
    }

    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % modulus;
        }
        base = (base * base) % modulus;
        exponent >>= 1;
    }

    printf("%llu\n", result);
    return 0;
}

