#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1) {
        return 0;
    }
    if (n <= 0) {
        printf("0\n");
        return 0;
    }

    long long sum = 0;
    for (long long i = 1; i <= n / i; ++i) {
        if (n % i == 0) {
            sum += i;
            if (i != n / i) {
                sum += n / i;
            }
        }
    }
    sum -= n; /* exclude n itself */

    printf("%lld\n", sum);
    return 0;
}

#include <stdio.h>

#define MAXN 1000000

static int cache[MAXN + 1];

static int collatz_length(long long x)
{
    if (x <= MAXN && cache[x] != 0) {
        return cache[x];
    }

    long long next = (x % 2 == 0) ? x / 2 : 3 * x + 1;
    int result = 1 + collatz_length(next);

    if (x <= MAXN) {
        cache[x] = result;
    }

    return result;
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 1) {
        return 0;
    }

    cache[1] = 1;

    for (int i = n; i >= 1; --i) {
        printf("%d\n", collatz_length(i));
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef unsigned long long u64;

static u64 factor_list[128];
static int factor_count = 0;

static u64 gcd_u64(u64 a, u64 b)
{
    while (b != 0) {
        u64 t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static u64 mulmod(u64 a, u64 b, u64 m)
{
    return (u64)((unsigned __int128)a * b % m);
}

static u64 powmod(u64 a, u64 e, u64 m)
{
    u64 r = 1 % m;
    a %= m;
    while (e != 0) {
        if (e & 1ULL) r = mulmod(r, a, m);
        a = mulmod(a, a, m);
        e >>= 1;
    }
    return r;
}

static int is_prime(u64 n)
{
    if (n < 2ULL) return 0;

    static const u64 small[] = {
        2ULL, 3ULL, 5ULL, 7ULL, 11ULL, 13ULL, 17ULL,
        19ULL, 23ULL, 29ULL, 31ULL, 37ULL
    };
    for (int i = 0; i < 12; i++) {
        if (n % small[i] == 0) return n == small[i];
    }

    u64 d = n - 1;
    int s = 0;
    while ((d & 1ULL) == 0) {
        d >>= 1;
        s++;
    }

    static const u64 bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL,
        450775ULL, 9780504ULL, 1795265022ULL
    };

    for (int i = 0; i < 7; i++) {
        u64 a = bases[i] % n;
        if (a == 0) continue;
        u64 x = powmod(a, d, n);
        if (x == 1ULL || x == n - 1ULL) continue;
        int composite = 1;
        for (int r = 1; r < s; r++) {
            x = mulmod(x, x, n);
            if (x == n - 1ULL) {
                composite = 0;
                break;
            }
        }
        if (composite) return 0;
    }
    return 1;
}

static u64 pollard_rho(u64 n)
{
    if (n % 2ULL == 0) return 2ULL;
    if (n % 3ULL == 0) return 3ULL;

    for (u64 c = 1; ; c++) {
        u64 x = 2, y = 2, d = 1;
        while (d == 1) {
            x = (mulmod(x, x, n) + c) % n;
            y = (mulmod(y, y, n) + c) % n;
            y = (mulmod(y, y, n) + c) % n;
            u64 diff = (x > y) ? (x - y) : (y - x);
            d = gcd_u64(diff, n);
        }
        if (d != n) return d;
    }
}

static void add_factor(u64 p)
{
    if (factor_count < 128) factor_list[factor_count++] = p;
}

static void factorize(u64 n)
{
    if (n == 1) return;

    for (u64 p = 2; p < 100000ULL && p * p <= n; p++) {
        while (n % p == 0) {
            add_factor(p);
            n /= p;
        }
    }

    if (n == 1) return;
    if (is_prime(n)) {
        add_factor(n);
        return;
    }

    u64 d = pollard_rho(n);
    factorize(d);
    factorize(n / d);
}

int main(void)
{
    u64 n;
    if (scanf("%llu", &n) != 1) return 0;

    if (n == 0) {
        printf("0\n");
        return 0;
    }
    if (n == 1) {
        printf("1\n");
        return 0;
    }

    factorize(n);

    u64 result = n;
    for (int i = 0; i < factor_count; i++) {
        int duplicate = 0;
        for (int j = 0; j < i; j++) {
            if (factor_list[j] == factor_list[i]) {
                duplicate = 1;
                break;
            }
        }
        if (!duplicate) {
            result = result / factor_list[i] * (factor_list[i] - 1);
        }
    }

    printf("%llu\n", result);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long vals[2];

    if (scanf("%lld %lld", &vals[0], &vals[1]) != 2) {
        return 1;
    }

    long long a = vals[0];
    long long b = vals[1];

    if (b < 0) {
        return 1;
    }

    long long result = 1;
    for (long long i = 0; i < b; ++i) {
        result *= a;
    }

    printf("%lld\n", result);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

static unsigned long long isqrt_ull(unsigned long long value)
{
    if (value == 0) {
        return 0;
    }

    unsigned long long lo = 1;
    unsigned long long hi = 3037000500ULL;

    while (lo <= hi) {
        unsigned long long mid = lo + (hi - lo) / 2;
        unsigned long long square = mid * mid;

        if (square == value) {
            return mid;
        }
        if (square < value) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    return hi;
}

int main(void)
{
    char input[256];
    size_t length = 0;
    int ch;

    while ((ch = getchar()) != EOF && length + 1 < sizeof(input)) {
        input[length++] = (char)ch;
    }
    input[length] = '\0';

    errno = 0;
    char *end = NULL;
    long long n = strtoll(input, &end, 10);

    if (end == input) {
        return 0;
    }

    int perfect = 0;
    if (n >= 0) {
        unsigned long long root = isqrt_ull((unsigned long long)n);
        perfect = (root * root == (unsigned long long)n);
    }

    puts(perfect ? "Yes" : "No");
    return 0;
}

