#include <stdio.h>

int main(void) {
    long long n;

    if (scanf("%lld", &n) != 1) {
        return 0;
    }

    if (n <= 0) {
        printf("0\n");
        return 0;
    }

    unsigned long long result = 1;
    while (result <= (unsigned long long)n / 2) {
        result <<= 1;
    }

    printf("%llu\n", result);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_LINE 65536

int main(void) {
    static char line[MAX_LINE];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        return 0;
    }

    size_t len = strlen(line);
    int had_newline = 0;

    if (len > 0 && line[len - 1] == '\n') {
        line[len - 1] = '\0';
        --len;
        had_newline = 1;
    }

    for (size_t i = 0; i < len / 2; ++i) {
        char tmp = line[i];
        line[i] = line[len - 1 - i];
        line[len - 1 - i] = tmp;
    }

    fputs(line, stdout);
    if (had_newline) {
        fputc('\n', stdout);
    }

    return 0;
}

