#include <stdio.h>

#define MAX_LINE (1 << 20)

static char line[MAX_LINE];

int main(void) {
    int c;
    size_t n = 0;

    while ((c = getchar()) != EOF && c != '\n') {
        if (n + 1 < MAX_LINE) {
            line[n++] = (char)c;
        }
    }
    line[n] = '\0';

    size_t left = 0;
    size_t right = n ? n - 1 : 0;
    int is_palindrome = 1;

    while (left < right) {
        while (left < right && line[left] == ' ') {
            ++left;
        }
        while (left < right && line[right] == ' ') {
            --right;
        }
        if (left >= right) {
            break;
        }
        if (line[left] != line[right]) {
            is_palindrome = 0;
            break;
        }
        ++left;
        --right;
    }

    printf("%d\n", is_palindrome);
    return 0;
}

