static int append_char(char **buf, size_t *cap, size_t *len, char c)
{
    if (*len + 2 > *cap) {
        size_t newcap = *cap ? *cap * 2 : 16;
        while (newcap < *len + 2) {
            newcap *= 2;
        }
        char *p = realloc(*buf, newcap);
        if (!p) {
            return -1;
        }
        *buf = p;
        *cap = newcap;
    }
    (*buf)[(*len)++] = c;
    (*buf)[*len] = '\0';
    return 0;
}

