{
    char *cur = NULL, *best = NULL;
    size_t curcap = 0, bestcap = 0, curlen = 0, bestlen = 0;

    int c;
    while ((c = getchar()) != EOF) {
        if (isspace((unsigned char)c)) {
            if (curlen > bestlen) {
                char *tmp = cur;
                cur = best;
                best = tmp;

                size_t tcap = curcap;
                curcap = bestcap;
                bestcap = tcap;

                size_t tlen = curlen;
                curlen = bestlen;
                bestlen = tlen;
            }
            curlen = 0;
            if (cur) {
                cur[0] = '\0';
