#define BASE 1000000000U

static void mul_add(uint32_t **limbs, size_t *count, size_t *capacity,
                    uint64_t multiplier, uint32_t chunk)
{
    size_t i;
    uint64_t carry = chunk;

    for (i = 0; i < *count; i++) {
        uint64_t value = (uint64_t)(*limbs)[i] * multiplier + carry;
        (*limbs)[i] = (uint32_t)(value % BASE);
        carry = value / BASE;
    }

    while (carry != 0) {
        if (*count == *capacity) {
            size_t new_capacity = (*capacity == 0) ? 16 : *capacity * 2;
            uint32_t *new_limbs = realloc(*limbs, new_capacity * sizeof(uint32_t));
            if (new_limbs == NULL) {
                perror("realloc");
                exit(EXIT_FAILURE);
            }
            *limbs = new_limbs;
            *capacity = new_capacity;
        }
        (*limbs)[(*count)++] = (uint32_t)(carry % BASE);
        carry /= BASE;
    }
}

static int hex_value(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

int main(void)
{
    size_t capacity = 16;
    size_t count = 1;
    uint32_t *limbs = malloc(capacity * sizeof(uint32_t));
    if (limbs == NULL) {
        perror("malloc");
        return EXIT_FAILURE;
    }
    limbs[0] = 0;

    uint32_t chunk = 0;
    int chunk_digits = 0;
    int c;

    while ((c = getchar()) != EOF) {
        int digit = hex_value(c);
        if (digit >= 0) {
            chunk = chunk * 16U + (uint32_t)digit;
            chunk_digits++;
            if (chunk_digits == 8) {
                mul_add(&limbs, &count, &capacity, 1ULL << 32, chunk);
                chunk = 0;
                chunk_digits = 0;
            }
        } else if (isspace((unsigned char)c)) {
            continue;
        } else {
            break;
        }
    }

    if (chunk_digits > 0) {
        uint64_t multiplier = 1;
        for (int i = 0; i < chunk_digits; i++) {
            multiplier *= 16ULL;
        }
        mul_add(&limbs, &count, &capacity, multiplier, chunk);
    }

    printf("%u", limbs[count - 1]);
    for (size_t i = count - 1; i-- > 0; ) {
        printf("%09u", limbs[i]);
    }
    putchar('\n');

    free(limbs);
    return 0;
}

