#include <stdio.h>

#define MAXN 1000000

static int arr[MAXN];

static void swap_int(int *a, int *b)
{
    int t = *a;
    *a = *b;
    *b = t;
}

static int partition(int a[], int lo, int hi)
{
    int pivot = a[lo + (hi - lo) / 2];
    int i = lo - 1;
    int j = hi + 1;

    for (;;) {
        do {
            ++i;
        } while (a[i] < pivot);
        do {
            --j;
        } while (a[j] > pivot);
        if (i >= j) {
            return j;
        }
        swap_int(&a[i], &a[j]);
    }
}

static void quicksort(int a[], int lo, int hi)
{
    if (lo < hi) {
        int p = partition(a, lo, hi);
        quicksort(a, lo, p);
        quicksort(a, p + 1, hi);
    }
}

int main(void)
{
    int n;

    if (scanf("%d", &n) != 1 || n < 0 || n > MAXN) {
        fprintf(stderr, "invalid n\n");
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "invalid input\n");
            return 1;
        }
    }

    if (n > 1) {
        quicksort(arr, 0, n - 1);
    }

    for (int i = 0; i < n; ++i) {
        if (i != 0) {
            putchar(' ');
        }
        printf("%d", arr[i]);
    }
    putchar('\n');

    return 0;
}

#include <stdio.h>

#define MAXN 100000

static int arr[MAXN];
static int helper[MAXN];

static void merge(int left, int mid, int right) {
    int i = left;
    int j = mid + 1;
    int k = left;

    while (i <= mid && j <= right) {
        if (arr[i] <= arr[j]) {
            helper[k++] = arr[i++];
        } else {
            helper[k++] = arr[j++];
        }
    }
    while (i <= mid) {
        helper[k++] = arr[i++];
    }
    while (j <= right) {
        helper[k++] = arr[j++];
    }
    for (k = left; k <= right; k++) {
        arr[k] = helper[k];
    }
}

static void merge_sort(int left, int right) {
    if (left >= right) return;
    int mid = left + (right - left) / 2;
    merge_sort(left, mid);
    merge_sort(mid + 1, right);
    merge(left, mid, right);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    if (n < 0 || n > MAXN) return 0;

    for (int i = 0; i < n; i++) {
        if (scanf("%d", &arr[i]) != 1) return 0;
    }

    if (n > 1) {
        merge_sort(0, n - 1);
    }

    for (int i = 0; i < n; i++) {
        if (i) putchar(' ');
        printf("%d", arr[i]);
    }
    if (n > 0) putchar('\n');
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXN 1000000

static void swap_int(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

static void sift_down(int arr[], int size, int root) {
    while (2 * root + 1 < size) {
        int child = 2 * root + 1;
        if (child + 1 < size && arr[child] < arr[child + 1]) {
            ++child;
        }
        if (arr[root] >= arr[child]) {
            break;
        }
        swap_int(&arr[root], &arr[child]);
        root = child;
    }
}

static void heap_sort(int arr[], int n) {
    for (int i = n / 2 - 1; i >= 0; --i) {
        sift_down(arr, n, i);
    }
    for (int end = n - 1; end > 0; --end) {
        swap_int(&arr[0], &arr[end]);
        sift_down(arr, end, 0);
    }
}

int main(void) {
    static int a[MAXN];

    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > MAXN) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            return EXIT_FAILURE;
        }
    }

    heap_sort(a, n);

    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            putchar(' ');
        }
        printf("%d", a[i]);
    }
    putchar('\n');

    return EXIT_SUCCESS;
}

#include <stdio.h>

#define MAX_N 1000000

static int a[MAX_N];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    if (n < 0 || n > MAX_N) {
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &a[i]) != 1) {
            return 0;
        }
    }

    int x;
    if (scanf("%d", &x) != 1) {
        return 0;
    }

    int lo = 0;
    int hi = n - 1;
    int result = -1;

    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == x) {
            result = mid;
            break;
        }
        if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    printf("%d\n", result);
    return 0;
}
